(295977,32887,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er will ein warmes Abendessen, ... brät er am Meer Fisch.'::text,'also'::text,'aber'::text,'weil'::text,'Er will ein warmes Abendessen, also brät er am Meer Fisch.'::text),
(295981,32887,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він хоче гарячу вечерю, ... смажить рибу біля моря.'::text,'тому'::text,'але'::text,'бо'::text,'Він хоче гарячу вечерю, тому смажить рибу біля моря.'::text),
(295980,32887,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él quiere una cena caliente, ... fríe pescado junto al mar.'::text,'así que'::text,'pero'::text,'porque'::text,'Él quiere una cena caliente, así que fríe pescado junto al mar.'::text),
(295979,32887,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il veut un dîner chaud, ... il fait frire du poisson au bord de la mer.'::text,'donc'::text,'mais'::text,'parce que'::text,'Il veut un dîner chaud, donc il fait frire du poisson au bord de la mer.'::text),
(295982,32887,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O sıcak bir akşam yemeği istiyor, ... deniz kenarında balık kızartıyor.'::text,'bu yüzden'::text,'ama'::text,'çünkü'::text,'O sıcak bir akşam yemeği istiyor, bu yüzden deniz kenarında balık kızartıyor.'::text),
(295983,32887,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő meleg vacsorát szeretne, ... halat süt a tengerparton.'::text,'ezért'::text,'de'::text,'mert'::text,'Ő meleg vacsorát szeretne, ezért halat süt a tengerparton.'::text),
(311232,34582,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, ... schiebt das Boot? Das ganze Dorf, muss ja helfen.'::text,'wer'::text,'was'::text,'wo'::text,'Digga, wer schiebt das Boot? Das ganze Dorf, muss ja helfen.'::text),
(311236,34582,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, ... штовхає човен? Усе село, треба ж допомогти.'::text,'хто'::text,'що'::text,'де'::text,'Бро, хто штовхає човен? Усе село, треба ж допомогти.'::text),
(311235,34582,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ¿... empuja el barco? Todo el pueblo, hay que ayudar.'::text,'quién'::text,'qué'::text,'dónde'::text,'Tío, ¿quién empuja el barco? Todo el pueblo, hay que ayudar.'::text),
(311234,34582,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, ... pousse le bateau ? Tout le village, faut bien aider.'::text,'qui'::text,'que'::text,'où'::text,'Frérot, qui pousse le bateau ? Tout le village, faut bien aider.'::text),
(311237,34582,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, tekneyi ... itiyor? Bütün köy, yardım etmek lazım.'::text,'kim'::text,'ne'::text,'nerede'::text,'Kanka, tekneyi kim itiyor? Bütün köy, yardım etmek lazım.'::text),
(311238,34582,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ... tolja a hajót? Az egész falu, segíteni kell.'::text,'ki'::text,'mi'::text,'hol'::text,'Tesó, ki tolja a hajót? Az egész falu, segíteni kell.'::text),
(311268,34586,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der alte Mann sagt, sie ... auf drei schieben.'::text,'sollten'::text,'sollten'::text,'sollten'::text,'Der alte Mann sagt, sie sollten auf drei schieben.'::text),
(311272,34586,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Старий каже, що вони ... штовхати на рахунок три.'::text,'мали б'::text,'мали б'::text,'мали б'::text,'Старий каже, що вони мали б штовхати на рахунок три.'::text),
(311271,34586,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El anciano dice que ellos ... empujar a la de tres.'::text,'deberían'::text,'deberían'::text,'deberían'::text,'El anciano dice que ellos deberían empujar a la de tres.'::text),
(311270,34586,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le vieil homme dit qu''ils ... pousser à trois.'::text,'devraient'::text,'devraient'::text,'devraient'::text,'Le vieil homme dit qu''ils devraient pousser à trois.'::text),
(311273,34586,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yaşlı adam diyor ki onlar üç deyince ...'::text,'itmeliler'::text,'itmeliler'::text,'itmeliler'::text,'Yaşlı adam diyor ki onlar üç deyince itmeliler.'::text),
(311274,34586,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az öreg azt mondja, hogy nekik háromra ... tolniuk.'::text,'kellene'::text,'kellene'::text,'kellene'::text,'Az öreg azt mondja, hogy nekik háromra kellene tolniuk.'::text),
(324291,36033,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Autos im Verkehr warten ... der Nacht im Regen.'::text,'in'::text,'in'::text,'an'::text,'Die Autos im Verkehr warten in der Nacht im Regen.'::text),
(324295,36033,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Машини в потоці чекають ... нічний час під дощем.'::text,'у'::text,'у'::text,'на'::text,'Машини в потоці чекають у нічний час під дощем.'::text),
(324294,36033,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los coches del tráfico esperan ... noche bajo la lluvia.'::text,'de'::text,'en'::text,'sobre'::text,'Los coches del tráfico esperan de noche bajo la lluvia.'::text),
(324293,36033,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les voitures dans la circulation attendent ... la nuit sous la pluie.'::text,''::text,'dans'::text,'sur'::text,'Les voitures dans la circulation attendent la nuit sous la pluie.'::text),
(324296,36033,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Trafikteki arabalar gece ... yağmurda bekliyor.'::text,''::text,NULL::text,NULL::text,'Trafikteki arabalar gece yağmurda bekliyor.'::text),
(324297,36033,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A forgalomban az autók ... várnak az esőben.'::text,'éjjel'::text,'éjszakában'::text,'éjszakán'::text,'A forgalomban az autók éjjel várnak az esőben.'::text),
(325461,36163,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Schiff in ihrem Urlaub hat ... Schornsteine.'::text,'zwei'::text,'zweite'::text,'zweimal'::text,'Das Schiff in ihrem Urlaub hat zwei Schornsteine.'::text),
(325465,36163,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Корабель у її відпустці має ... труби.'::text,'дві'::text,'другі'::text,'двічі'::text,'Корабель у її відпустці має дві труби.'::text),
(325464,36163,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El barco de sus vacaciones tiene ... chimeneas.'::text,'dos'::text,'segundas'::text,'dos veces'::text,'El barco de sus vacaciones tiene dos chimeneas.'::text),
(325463,36163,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le bateau de ses vacances a ... cheminées.'::text,'deux'::text,'deuxièmes'::text,'deux fois'::text,'Le bateau de ses vacances a deux cheminées.'::text),
(325466,36163,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tatilindeki geminin ... bacası var.'::text,'iki'::text,'ikinci'::text,'iki kez'::text,'Tatilindeki geminin iki bacası var.'::text),
(325467,36163,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nyaralásán lévő hajónak ... kéménye van.'::text,'két'::text,'második'::text,'kétszer'::text,'A nyaralásán lévő hajónak két kéménye van.'::text),
(315633,35071,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Absolut! Dieses Schiff ist für immer ... neues Zuhause!'::text,'ihr'::text,'sein'::text,'sein'::text,'Absolut! Dieses Schiff ist für immer ihr neues Zuhause!'::text),
(315637,35071,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Абсолютно! Цей корабель — ... новий дім назавжди!'::text,'її'::text,'його'::text,'його'::text,'Абсолютно! Цей корабель — її новий дім назавжди!'::text),
(315636,35071,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Totalmente! ¡Este barco es ... nuevo hogar para siempre!'::text,'su'::text,'su'::text,'su'::text,'¡Totalmente! ¡Este barco es su nuevo hogar para siempre!'::text),
(315635,35071,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Absolument ! Ce bateau est ... nouvelle maison pour toujours !'::text,'sa'::text,'sa'::text,'sa'::text,'Absolument ! Ce bateau est sa nouvelle maison pour toujours !'::text),
(315638,35071,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kesinlikle! Bu gemi sonsuza dek ... yeni evi!'::text,'onun'::text,'onun'::text,'onun'::text,'Kesinlikle! Bu gemi sonsuza dek onun yeni evi!'::text),
(315639,35071,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Abszolút! Ez a hajó örökre az új ...!'::text,'otthona'::text,'otthona'::text,'otthona'::text,'Abszolút! Ez a hajó örökre az új otthona!'::text),
(315642,35072,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Albtraum! Das Buffet auf dem Schiff hatte so viel ...!'::text,'Essen'::text,'Essen'::text,'Mahlzeiten'::text,'Albtraum! Das Buffet auf dem Schiff hatte so viel Essen!'::text),
(315646,35072,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жах! На шведському столі на кораблі було стільки ...!'::text,'їжі'::text,'їжі'::text,'страв'::text,'Жах! На шведському столі на кораблі було стільки їжі!'::text),
(315645,35072,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Pesadilla! ¡El bufé del barco tenía tanta ...!'::text,'comida'::text,'comida'::text,'platos'::text,'¡Pesadilla! ¡El bufé del barco tenía tanta comida!'::text),
(315644,35072,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cauchemar ! Le buffet du bateau avait tellement de ... !'::text,'nourriture'::text,'nourriture'::text,'repas'::text,'Cauchemar ! Le buffet du bateau avait tellement de nourriture !'::text),
(315647,35072,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kâbus! Geminin açık büfesinde o kadar çok ... vardı ki!'::text,'yemek'::text,'yemekler'::text,'öğün'::text,'Kâbus! Geminin açık büfesinde o kadar çok yemek vardı ki!'::text),
(315648,35072,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rémálom! A hajó büféjében annyi ... volt!'::text,'étel'::text,'étel'::text,'fogás'::text,'Rémálom! A hajó büféjében annyi étel volt!'::text),
(300432,33382,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er läuft auf Krücken ... Krankenhausflur.'::text,'im'::text,'auf dem'::text,'am'::text,'Er läuft auf Krücken im Krankenhausflur.'::text),
(300436,33382,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він іде на милицях ... лікарняному коридору.'::text,'по'::text,'на'::text,'біля'::text,'Він іде на милицях по лікарняному коридору.'::text),
(300435,33382,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él camina con muletas ... el pasillo del hospital.'::text,'por'::text,'sobre'::text,'a'::text,'Él camina con muletas por el pasillo del hospital.'::text),
(300434,33382,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il marche avec des béquilles ... le couloir de l''hôpital.'::text,'dans'::text,'sur'::text,'à'::text,'Il marche avec des béquilles dans le couloir de l''hôpital.'::text),
(300437,33382,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, koltuk değnekleriyle hastane koridorunun ... yürüyor.'::text,'içinde'::text,'üstünde'::text,NULL::text,'O, koltuk değnekleriyle hastane koridorunun içinde yürüyor.'::text),
(300438,33382,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő mankóval megy a kórházi ...'::text,'folyosón'::text,'folyosón'::text,'folyosónál'::text,'Ő mankóval megy a kórházi folyosón.'::text),
(300450,33384,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Auf beiden Seiten des Krankenhausflurs ... Handläufe.'::text,'sind'::text,'ist'::text,'sein'::text,'Auf beiden Seiten des Krankenhausflurs sind Handläufe.'::text),
(300454,33384,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'По обидва боки лікарняного коридору ... поручні.'::text,'є'::text,'є'::text,'бути'::text,'По обидва боки лікарняного коридору є поручні.'::text),
(300453,33384,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... pasamanos a ambos lados del pasillo del hospital.'::text,'Hay'::text,'Hay'::text,'Hay'::text,'Hay pasamanos a ambos lados del pasillo del hospital.'::text),
(300452,33384,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... des rampes des deux côtés du couloir de l''hôpital.'::text,'Il y a'::text,'Il y a'::text,'Il y a'::text,'Il y a des rampes des deux côtés du couloir de l''hôpital.'::text),
(300455,33384,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hastane koridorunun iki yanında da tırabzanlar ...'::text,'var'::text,'var'::text,'olmak'::text,'Hastane koridorunun iki yanında da tırabzanlar var.'::text),
(300456,33384,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kórházi folyosó mindkét oldalán korlátok ...'::text,'vannak'::text,'van'::text,'lenni'::text,'A kórházi folyosó mindkét oldalán korlátok vannak.'::text),
(323238,35916,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wir ... für immer zusammen! Kein Abschied, niemals!'::text,'sind'::text,'ist'::text,'bin'::text,'Wir sind für immer zusammen! Kein Abschied, niemals!'::text),
(323242,35916,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ми ... разом назавжди! Жодних прощань, ніколи!'::text,'є'::text,'є'::text,'є'::text,'Ми є разом назавжди! Жодних прощань, ніколи!'::text),
(323241,35916,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Nosotros ... juntos para siempre! ¡Sin despedidas, nunca!'::text,'estamos'::text,'está'::text,'estoy'::text,'¡Nosotros estamos juntos para siempre! ¡Sin despedidas, nunca!'::text),
(323240,35916,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nous ... ensemble pour toujours ! Pas d''adieux, jamais !'::text,'sommes'::text,'est'::text,'suis'::text,'Nous sommes ensemble pour toujours ! Pas d''adieux, jamais !'::text),
(323243,35916,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Biz sonsuza dek birlikte ...! Veda yok, asla!'::text,''::text,NULL::text,NULL::text,'Biz sonsuza dek birlikte! Veda yok, asla!'::text),
(323244,35916,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mi örökre együtt ...! Semmi búcsú, soha!'::text,'vagyunk'::text,'van'::text,'vagyok'::text,'Mi örökre együtt vagyunk! Semmi búcsú, soha!'::text),
(323292,35922,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zusammen sind die Freunde ... als allein.'::text,'glücklicher'::text,'glücklicher'::text,'am glücklichsten'::text,'Zusammen sind die Freunde glücklicher als allein.'::text),
(323296,35922,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Разом друзі ..., ніж були поодинці.'::text,'щасливіші'::text,'більш щасливі'::text,'найщасливіші'::text,'Разом друзі щасливіші, ніж були поодинці.'::text),
(323295,35922,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Juntos, los amigos son ... que cuando estaban solos.'::text,'más felices'::text,'más felices'::text,'los más felices'::text,'Juntos, los amigos son más felices que cuando estaban solos.'::text),
(323294,35922,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ensemble, les amis sont ... que lorsqu''ils étaient seuls.'::text,'plus heureux'::text,'plus heureux'::text,'les plus heureux'::text,'Ensemble, les amis sont plus heureux que lorsqu''ils étaient seuls.'::text),
(323297,35922,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arkadaşlar birlikteyken, yalnız olduklarından ...'::text,'daha mutlu'::text,'daha mutlu'::text,'en mutlu'::text,'Arkadaşlar birlikteyken, yalnız olduklarından daha mutlu.'::text),
(323298,35922,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Együtt a barátok ..., mint egyedül.'::text,'boldogabbak'::text,'boldogabbak'::text,'legboldogabbak'::text,'Együtt a barátok boldogabbak, mint egyedül.'::text),
(306696,34078,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie nimmt ein Taschentuch und putzt sich die Nase in ... Taschentuch.'::text,'das'::text,'ein'::text,'ein'::text,'Sie nimmt ein Taschentuch und putzt sich die Nase in das Taschentuch.'::text),
(306700,34078,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона бере серветку й сякається в ... серветку.'::text,''::text,NULL::text,NULL::text,'Вона бере серветку й сякається в серветку.'::text),
(306699,34078,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella coge un pañuelo y se suena la nariz con ... pañuelo.'::text,'el'::text,'un'::text,'un'::text,'Ella coge un pañuelo y se suena la nariz con el pañuelo.'::text),
(306698,34078,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle prend un mouchoir et se mouche dans ... mouchoir.'::text,'le'::text,'un'::text,'un'::text,'Elle prend un mouchoir et se mouche dans le mouchoir.'::text),
(306701,34078,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O bir mendil alıyor ve burnunu ... mendile siliyor.'::text,''::text,'bir'::text,'bir'::text,'O bir mendil alıyor ve burnunu mendile siliyor.'::text),
(306702,34078,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő fog egy zsebkendőt, és kifújja az orrát ... zsebkendőbe.'::text,'a'::text,'egy'::text,'egy'::text,'Ő fog egy zsebkendőt, és kifújja az orrát a zsebkendőbe.'::text),
(306723,34081,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie weint so sehr, dass ihre Nase viele ... braucht.'::text,'Taschentücher'::text,'Taschentuch'::text,'ein Taschentuch'::text,'Sie weint so sehr, dass ihre Nase viele Taschentücher braucht.'::text),
(306727,34081,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона так плаче, що її носу потрібно багато ...'::text,'серветок'::text,'серветки'::text,'серветки'::text,'Вона так плаче, що її носу потрібно багато серветок.'::text),
(306726,34081,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella llora tanto que su nariz necesita muchos ...'::text,'pañuelos'::text,'pañuelo'::text,'un pañuelo'::text,'Ella llora tanto que su nariz necesita muchos pañuelos.'::text),
(306725,34081,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle pleure tellement que son nez a besoin de beaucoup de ...'::text,'mouchoirs'::text,'mouchoir'::text,'un mouchoir'::text,'Elle pleure tellement que son nez a besoin de beaucoup de mouchoirs.'::text),
(306728,34081,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, o kadar çok ağlıyor ki burnunun birçok ... ihtiyacı var.'::text,'mendile'::text,'mendile'::text,'bir mendile'::text,'O, o kadar çok ağlıyor ki burnunun birçok mendile ihtiyacı var.'::text),
(306729,34081,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő annyit sír, hogy az orrának sok ... kell.'::text,'zsebkendő'::text,'zsebkendő'::text,'egy zsebkendő'::text,'Ő annyit sír, hogy az orrának sok zsebkendő kell.'::text),
(313347,34817,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich gesagt, auf dieser Straße ... kein Fahrer wie du.'::text,'ist'::text,'sind'::text,'sein'::text,'Ehrlich gesagt, auf dieser Straße ist kein Fahrer wie du.'::text),
(313351,34817,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, на цій дорозі ... такого велосипедиста, як ти.'::text,'немає'::text,'немає'::text,'бути'::text,'Чесно, на цій дорозі немає такого велосипедиста, як ти.'::text),
(313350,34817,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No te voy a mentir, ... ningún ciclista como tú en esta carretera.'::text,'no hay'::text,'no hay'::text,'no hay'::text,'No te voy a mentir, no hay ningún ciclista como tú en esta carretera.'::text),
(313349,34817,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sans mentir, ... aucun cycliste comme toi sur cette route.'::text,'il n''y a'::text,'il n''y a'::text,'il n''y a'::text,'Sans mentir, il n''y a aucun cycliste comme toi sur cette route.'::text),
(313352,34817,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, bu yolda senin gibi bir sürücü ...'::text,'yok'::text,'yok'::text,'olmak'::text,'Yalan yok, bu yolda senin gibi bir sürücü yok.'::text),
(313353,34817,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hazudok, ezen az úton ... olyan bringás, mint te.'::text,'nincs'::text,'nincsenek'::text,'lenni'::text,'Nem hazudok, ezen az úton nincs olyan bringás, mint te.'::text),
(323868,35986,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ist die Uhr? Am alten Turm.'::text,'Wo'::text,'Was'::text,'Wer'::text,'Wo ist die Uhr? Am alten Turm.'::text),
(323872,35986,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... годинник? На старій вежі.'::text,'Де'::text,'Що'::text,'Хто'::text,'Де годинник? На старій вежі.'::text),
(323871,35986,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... está el reloj? En la torre antigua.'::text,'Dónde'::text,'Qué'::text,'Quién'::text,'¿Dónde está el reloj? En la torre antigua.'::text),
(323870,35986,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... est l''horloge ? Sur la vieille tour.'::text,'Où'::text,'Que'::text,'Qui'::text,'Où est l''horloge ? Sur la vieille tour.'::text),
(323873,35986,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saat ...? Eski kulede.'::text,'nerede'::text,'ne'::text,'kim'::text,'Saat nerede? Eski kulede.'::text),
(323874,35986,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... van az óra? A régi tornyon.'::text,'Hol'::text,'Mi'::text,'Ki'::text,'Hol van az óra? A régi tornyon.'::text),
(314985,34999,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Kunde will Pfirsiche, also ... ihm der Mann morgen mehr verkaufen.'::text,'wird'::text,'verkaufte'::text,'verkaufte'::text,'Der Kunde will Pfirsiche, also wird ihm der Mann morgen mehr verkaufen.'::text),
(314989,34999,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Покупець хоче персиків, тож завтра чоловік ... йому ще.'::text,'продасть'::text,'продав'::text,'продав'::text,'Покупець хоче персиків, тож завтра чоловік продасть йому ще.'::text),
(314988,34999,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El cliente quiere melocotones, así que mañana el hombre le ... más.'::text,'venderá'::text,'vendió'::text,'vendió'::text,'El cliente quiere melocotones, así que mañana el hombre le venderá más.'::text),
(314987,34999,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le client veut des pêches, alors demain l''homme lui en ... davantage.'::text,'vendra'::text,'a vendu'::text,'a vendu'::text,'Le client veut des pêches, alors demain l''homme lui en vendra davantage.'::text),
(314990,34999,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Müşteri şeftali istiyor, bu yüzden adam yarın ona daha fazla ...'::text,'satacak'::text,'sattı'::text,'sattı'::text,'Müşteri şeftali istiyor, bu yüzden adam yarın ona daha fazla satacak.'::text),
(314991,34999,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vevő barackot akar, ezért holnap a férfi még többet ... neki.'::text,'fog eladni'::text,'eladott'::text,'eladott'::text,'A vevő barackot akar, ezért holnap a férfi még többet fog eladni neki.'::text),
(311727,34637,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Lowkey beeindruckend, du ... das rohe Hähnchen wie ein echter Koch.'::text,'wäschst'::text,'wäscht'::text,'waschend'::text,'Lowkey beeindruckend, du wäschst das rohe Hähnchen wie ein echter Koch.'::text),
(311731,34637,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Лоукі вражає: ти ... сиру курку як справжній шеф.'::text,'миєш'::text,'миє'::text,'миючи'::text,'Лоукі вражає: ти миєш сиру курку як справжній шеф.'::text),
(311730,34637,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, impresionante: tú ... el pollo crudo como un chef de verdad.'::text,'lavas'::text,'lava'::text,'lavando'::text,'La verdad, impresionante: tú lavas el pollo crudo como un chef de verdad.'::text),
(311729,34637,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Discrètement impressionnant, tu ... le poulet cru comme un vrai chef.'::text,'laves'::text,'lave'::text,'lavant'::text,'Discrètement impressionnant, tu laves le poulet cru comme un vrai chef.'::text),
(311732,34637,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası etkileyici, sen çiğ tavuğu gerçek bir şef gibi ...'::text,'yıkarsın'::text,'yıkar'::text,'yıkayarak'::text,'Açıkçası etkileyici, sen çiğ tavuğu gerçek bir şef gibi yıkarsın.'::text),
(311733,34637,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Lowkey lenyűgöző, te úgy ... a nyers csirkét, mint egy igazi séf.'::text,'mosod'::text,'mossa'::text,'mosó'::text,'Lowkey lenyűgöző, te úgy mosod a nyers csirkét, mint egy igazi séf.'::text),
(311763,34641,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Hähnchen ist roh, also ... er sich danach die Hände waschen.'::text,'sollte'::text,'sollte'::text,'sollte'::text,'Das Hähnchen ist roh, also sollte er sich danach die Hände waschen.'::text),
(311767,34641,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Курка сира, тож він ... потім помити руки.'::text,'мав би'::text,'мав би'::text,'мав би'::text,'Курка сира, тож він мав би потім помити руки.'::text),
(311766,34641,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El pollo está crudo, así que él ... lavarse las manos después.'::text,'debería'::text,'debería'::text,'debería'::text,'El pollo está crudo, así que él debería lavarse las manos después.'::text),
(311765,34641,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le poulet est cru, donc il ... se laver les mains après.'::text,'devrait'::text,'devrait'::text,'devrait'::text,'Le poulet est cru, donc il devrait se laver les mains après.'::text),
(311768,34641,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tavuk çiğ, bu yüzden o sonra ellerini ...'::text,'yıkamalı'::text,'yıkamalı'::text,'yıkamalı'::text,'Tavuk çiğ, bu yüzden o sonra ellerini yıkamalı.'::text),
(311769,34641,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A csirke nyers, ezért neki utána ... kezet mosnia.'::text,'kellene'::text,'kellene'::text,'kellene'::text,'A csirke nyers, ezért neki utána kellene kezet mosnia.'::text),
(308424,34270,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zwei Männer und eine Frau schlafen, also schlafen ... Passagiere.'::text,'drei'::text,'dritte'::text,'Dreien'::text,'Zwei Männer und eine Frau schlafen, also schlafen drei Passagiere.'::text),
(308428,34270,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Двоє чоловіків і одна жінка сплять, тож ... пасажири сплять.'::text,'три'::text,'треті'::text,'трійки'::text,'Двоє чоловіків і одна жінка сплять, тож три пасажири сплять.'::text),
(308427,34270,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dos hombres y una mujer duermen, así que ... pasajeros están dormidos.'::text,'tres'::text,'terceros'::text,'tres'::text,'Dos hombres y una mujer duermen, así que tres pasajeros están dormidos.'::text),
(308426,34270,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Deux hommes et une femme dorment, donc ... passagers sont endormis.'::text,'trois'::text,'troisièmes'::text,'trois'::text,'Deux hommes et une femme dorment, donc trois passagers sont endormis.'::text),
(308429,34270,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İki adam ve bir kadın uyuyor, yani ... yolcu uykuda.'::text,'üç'::text,'üçüncü'::text,'üçler'::text,'İki adam ve bir kadın uyuyor, yani üç yolcu uykuda.'::text),
(308430,34270,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Két férfi és egy nő alszik, tehát ... utas alszik.'::text,'három'::text,'harmadik'::text,'hármasok'::text,'Két férfi és egy nő alszik, tehát három utas alszik.'::text),
(308433,34271,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Passagierin des Jahres: Du ... dein Reisekissen mit Stil, ehrlich.'::text,'trägst'::text,'trägst'::text,'trägst'::text,'Passagierin des Jahres: Du trägst dein Reisekissen mit Stil, ehrlich.'::text),
(308437,34271,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Пасажирка року: ти ... свою дорожню подушку зі стилем, чесно.'::text,'носиш'::text,'носиш'::text,'носиш'::text,'Пасажирка року: ти носиш свою дорожню подушку зі стилем, чесно.'::text),
(308436,34271,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pasajera del año: tú ... tu almohada de viaje con estilo, en serio.'::text,'estás llevando'::text,'llevas'::text,'estás llevando'::text,'Pasajera del año: tú estás llevando tu almohada de viaje con estilo, en serio.'::text),
(308435,34271,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Passagère de l''année : tu ... ton coussin de voyage avec style, franchement.'::text,'es en train de porter'::text,'portes'::text,'es en train de porter'::text,'Passagère de l''année : tu es en train de porter ton coussin de voyage avec style, franchement.'::text),
(308438,34271,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yılın yolcusu: sen seyahat yastığını tarzla ..., cidden.'::text,'takıyorsun'::text,'takarsın'::text,'takıyorsun'::text,'Yılın yolcusu: sen seyahat yastığını tarzla takıyorsun, cidden.'::text),
(308439,34271,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az év utasa: te stílusosan ... az utazópárnádat, komolyan.'::text,'viseled'::text,'viseled'::text,'viseled'::text,'Az év utasa: te stílusosan viseled az utazópárnádat, komolyan.'::text),
(326127,36237,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gestern Abend ... die Wahlhelfer jede Stimme auf dem Tisch.'::text,'zählten'::text,'zählt'::text,'zählten'::text,'Gestern Abend zählten die Wahlhelfer jede Stimme auf dem Tisch.'::text),
(326131,36237,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Учора ввечері посадовці ... кожен голос на столі.'::text,'порахували'::text,'рахує'::text,'порахували'::text,'Учора ввечері посадовці порахували кожен голос на столі.'::text),
(326130,36237,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Anoche los funcionarios ... cada voto sobre la mesa.'::text,'contaron'::text,'cuenta'::text,'contaron'::text,'Anoche los funcionarios contaron cada voto sobre la mesa.'::text),
(326129,36237,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hier soir, les responsables ... chaque vote sur la table.'::text,'ont compté'::text,'compte'::text,'ont compté'::text,'Hier soir, les responsables ont compté chaque vote sur la table.'::text),
(326132,36237,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dün gece görevliler masadaki her oyu ...'::text,'saydı'::text,'sayar'::text,'saydı'::text,'Dün gece görevliler masadaki her oyu saydı.'::text),
(326133,36237,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tegnap este a tisztviselők ... az összes szavazatot az asztalon.'::text,'megszámolták'::text,'megszámolja'::text,'megszámolták'::text,'Tegnap este a tisztviselők megszámolták az összes szavazatot az asztalon.'::text),
(303312,33702,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... das Schiff jetzt ablegen? Ja, kann es.'::text,'Kann'::text,NULL::text,'Ist'::text,'Kann das Schiff jetzt ablegen? Ja, kann es.'::text),
(303316,33702,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чи ... корабель відплисти зараз? Так, може.'::text,'може'::text,NULL::text,'є'::text,'Чи може корабель відплисти зараз? Так, може.'::text),
(303315,33702,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... el barco zarpar ahora? Sí, puede.'::text,'Puede'::text,NULL::text,'Está'::text,'¿Puede el barco zarpar ahora? Sí, puede.'::text),
(303314,33702,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Est-ce que le bateau ... partir maintenant ? Oui, il peut.'::text,'peut'::text,NULL::text,'est'::text,'Est-ce que le bateau peut partir maintenant ? Oui, il peut.'::text),
(303317,33702,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gemi şimdi ... mi? Evet, kalkabilir.'::text,'kalkabilir'::text,NULL::text,NULL::text,'Gemi şimdi kalkabilir mi? Evet, kalkabilir.'::text),
(303318,33702,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... most a hajó? Igen, indulhat.'::text,'Indulhat'::text,NULL::text,'Van'::text,'Indulhat most a hajó? Igen, indulhat.'::text),
(303330,33704,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, der Zug ... ab und er hat einfach weitergewinkt, ohne Witz.'::text,'fuhr'::text,'fährt'::text,'fuhr'::text,'Digga, der Zug fuhr ab und er hat einfach weitergewinkt, ohne Witz.'::text),
(303334,33704,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, потяг ... а він просто далі махав, без брехні.'::text,'поїхав'::text,'їде'::text,'поїхав'::text,'Бро, потяг поїхав а він просто далі махав, без брехні.'::text),
(303333,33704,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, el tren se ... y él siguió saludando, sin mentir.'::text,'fue'::text,'va'::text,'fue'::text,'Tío, el tren se fue y él siguió saludando, sin mentir.'::text),
(303332,33704,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, le train ... et lui, il a continué à faire coucou, sans mentir.'::text,'est parti'::text,'part'::text,'est parti'::text,'Frérot, le train est parti et lui, il a continué à faire coucou, sans mentir.'::text),
(303335,33704,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, tren ... ve o el sallamaya devam etti, yemin ederim.'::text,'gitti'::text,'gider'::text,'gitti'::text,'Kanka, tren gitti ve o el sallamaya devam etti, yemin ederim.'::text),
(303336,33704,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a vonat ..., ő meg csak integetett tovább, komolyan.'::text,'elment'::text,'elmegy'::text,'elment'::text,'Tesó, a vonat elment, ő meg csak integetett tovább, komolyan.'::text),
(314058,34896,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee Mann, er ... so traurig, kein Picknick, gleich heult er.'::text,'ist'::text,'sind'::text,'bin'::text,'Nee Mann, er ist so traurig, kein Picknick, gleich heult er.'::text),
(314062,34896,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ні, чувак, він ... такий сумний, ніякого пікніка, зараз заплаче.'::text,'є'::text,'є'::text,'є'::text,'Ні, чувак, він є такий сумний, ніякого пікніка, зараз заплаче.'::text),
(314061,34896,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, tío, él ... tan triste, sin pícnic, va a llorar.'::text,'está'::text,'están'::text,'estoy'::text,'Qué va, tío, él está tan triste, sin pícnic, va a llorar.'::text),
(314060,34896,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Non mec, il ... trop triste, pas de pique-nique, il va pleurer.'::text,'est'::text,'sont'::text,'suis'::text,'Non mec, il est trop triste, pas de pique-nique, il va pleurer.'::text),
(314063,34896,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok kanka, o çok üzgün ..., piknik yok, ağlayacak.'::text,''::text,NULL::text,NULL::text,'Yok kanka, o çok üzgün, piknik yok, ağlayacak.'::text),
(314064,34896,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem, haver, ő ... annyira szomorú, nincs piknik, mindjárt sír.'::text,''::text,NULL::text,'vagyok'::text,'Nem, haver, ő annyira szomorú, nincs piknik, mindjárt sír.'::text),
(314094,34900,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ist jetzt traurig, aber morgen ... er sein Picknick haben.'::text,'wird'::text,'ist'::text,'war'::text,'Er ist jetzt traurig, aber morgen wird er sein Picknick haben.'::text),
(314098,34900,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він зараз сумний, але завтра в нього ... пікнік.'::text,'буде'::text,'є'::text,'був'::text,'Він зараз сумний, але завтра в нього буде пікнік.'::text),
(314097,34900,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él está triste ahora, pero mañana ... tener su pícnic.'::text,''::text,'está'::text,'estaba'::text,'Él está triste ahora, pero mañana tener su pícnic.'::text),
(314096,34900,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il est triste maintenant, mais demain il ... avoir son pique-nique.'::text,''::text,'est'::text,'était'::text,'Il est triste maintenant, mais demain il avoir son pique-nique.'::text),
(314099,34900,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O şimdi üzgün ama yarın pikniğini ...'::text,'yapacak'::text,NULL::text,'idi'::text,'O şimdi üzgün ama yarın pikniğini yapacak.'::text),
(314100,34900,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő most szomorú, de holnap meg ... tartani a piknikjét.'::text,'fogja'::text,'van'::text,'volt'::text,'Ő most szomorú, de holnap meg fogja tartani a piknikjét.'::text),
(298326,33148,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, aber der Friseur hat eine Linie in ... Haarschnitt rasiert, irgendwie ikonisch.'::text,'seinen'::text,'ihren'::text,'ihren'::text,'Okay, aber der Friseur hat eine Linie in seinen Haarschnitt rasiert, irgendwie ikonisch.'::text),
(298330,33148,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Окей, але барбер виголив лінію на ... стрижці, трохи культово.'::text,'його'::text,'її'::text,'їхній'::text,'Окей, але барбер виголив лінію на його стрижці, трохи культово.'::text),
(298329,33148,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pero el barbero le rapó una línea en ... corte, bastante icónico.'::text,'su'::text,'su'::text,'su'::text,'Vale, pero el barbero le rapó una línea en su corte, bastante icónico.'::text),
(298328,33148,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ok, mais le barbier a rasé une ligne dans ... coupe, plutôt iconique.'::text,'sa'::text,'sa'::text,'leur'::text,'Ok, mais le barbier a rasé une ligne dans sa coupe, plutôt iconique.'::text),
(298331,33148,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam ama berber ... saç kesimine bir çizgi kazıdı, baya ikonik.'::text,'onun'::text,'onun'::text,'onların'::text,'Tamam ama berber onun saç kesimine bir çizgi kazıdı, baya ikonik.'::text),
(298332,33148,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, de a borbély egy csíkot borotvált a ..., elég ikonikus.'::text,'frizurájába'::text,'frizurájába'::text,'frizurájukba'::text,'Oké, de a borbély egy csíkot borotvált a frizurájába, elég ikonikus.'::text),
(298353,33151,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'In seinem Haarschnitt ... eine Linie, weil der Friseur sie dort hingemacht hat.'::text,'ist'::text,'sind'::text,'sein'::text,'In seinem Haarschnitt ist eine Linie, weil der Friseur sie dort hingemacht hat.'::text),
(298357,33151,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У його стрижці ... лінія, бо барбер її туди зробив.'::text,'є'::text,'є'::text,'бути'::text,'У його стрижці є лінія, бо барбер її туди зробив.'::text),
(298356,33151,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... una línea en su corte porque el barbero la puso ahí.'::text,'Hay'::text,'Hay'::text,'Hay'::text,'Hay una línea en su corte porque el barbero la puso ahí.'::text),
(298355,33151,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... une ligne dans sa coupe parce que le barbier l''a mise là.'::text,'Il y a'::text,'Il y a'::text,'Il y a'::text,'Il y a une ligne dans sa coupe parce que le barbier l''a mise là.'::text),
(298358,33151,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onun saç kesiminde bir çizgi ... çünkü berber onu oraya yaptı.'::text,'var'::text,'var'::text,'olmak'::text,'Onun saç kesiminde bir çizgi var çünkü berber onu oraya yaptı.'::text),
(298359,33151,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A frizurájában ... egy csík, mert a borbély oda tette.'::text,'van'::text,'vannak'::text,'lenni'::text,'A frizurájában van egy csík, mert a borbély oda tette.'::text),
(311799,34645,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jeden Sommer wandert sie hierher, und gestern Abend ... sie die Bucht.'::text,'erreichte'::text,'erreicht'::text,NULL::text,'Jeden Sommer wandert sie hierher, und gestern Abend erreichte sie die Bucht.'::text),
(311803,34645,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Щоліта вона ходить сюди, а вчора ввечері вона ... до затоки.'::text,'дійшла'::text,'доходить'::text,NULL::text,'Щоліта вона ходить сюди, а вчора ввечері вона дійшла до затоки.'::text),
(311802,34645,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella camina hasta aquí cada verano, y anoche ... a la bahía.'::text,'llegó'::text,'llega'::text,NULL::text,'Ella camina hasta aquí cada verano, y anoche llegó a la bahía.'::text),
(311801,34645,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Chaque été, elle marche jusqu''ici, et hier soir elle ... la baie.'::text,'a atteint'::text,'atteint'::text,NULL::text,'Chaque été, elle marche jusqu''ici, et hier soir elle a atteint la baie.'::text),
(311804,34645,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O her yaz buraya yürür ve dün akşam koya ...'::text,'ulaştı'::text,'ulaşır'::text,NULL::text,'O her yaz buraya yürür ve dün akşam koya ulaştı.'::text),
(311805,34645,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő minden nyáron ide sétál, és tegnap este ... az öbölhöz.'::text,'odaért'::text,'odaér'::text,NULL::text,'Ő minden nyáron ide sétál, és tegnap este odaért az öbölhöz.'::text),
(309585,34399,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zehn Kisten plus zwei Taschen: ehrlich, dein Stapel hat ... Sachen.'::text,'zwölf'::text,'zwölfte'::text,'Zwölfen'::text,'Zehn Kisten plus zwei Taschen: ehrlich, dein Stapel hat zwölf Sachen.'::text),
(309589,34399,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Десять коробок плюс дві сумки: чесно, у твоїй купі ... речей.'::text,'дванадцять'::text,'дванадцята'::text,'дванадцятки'::text,'Десять коробок плюс дві сумки: чесно, у твоїй купі дванадцять речей.'::text),
(309588,34399,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Diez cajas más dos bolsas: en serio, tu montón tiene ... cosas.'::text,'doce'::text,'duodécimas'::text,'doce'::text,'Diez cajas más dos bolsas: en serio, tu montón tiene doce cosas.'::text),
(309587,34399,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dix boîtes plus deux sacs : franchement, ta pile a ... choses.'::text,'douze'::text,'douzièmes'::text,'douze'::text,'Dix boîtes plus deux sacs : franchement, ta pile a douze choses.'::text),
(309590,34399,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On kutu artı iki çanta: açıkçası yığınında ... şey var.'::text,'on iki'::text,'on ikinci'::text,'on ikiler'::text,'On kutu artı iki çanta: açıkçası yığınında on iki şey var.'::text),
(309591,34399,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tíz doboz plusz két táska: őszintén, a kupacodban ... dolog van.'::text,'tizenkét'::text,'tizenkettedik'::text,'tizenkettesek'::text,'Tíz doboz plusz két táska: őszintén, a kupacodban tizenkét dolog van.'::text),
(309630,34404,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihre Kisten liegen auf einem Haufen. Ich glaube, dass ihr ein Kunde ...'::text,'helfen wird'::text,'helfen wird'::text,NULL::text,'Ihre Kisten liegen auf einem Haufen. Ich glaube, dass ihr ein Kunde helfen wird.'::text),
(309634,34404,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її коробки лежать купою. Я думаю, якийсь покупець ... їй.'::text,'допоможе'::text,'збирається допомогти'::text,NULL::text,'Її коробки лежать купою. Я думаю, якийсь покупець допоможе їй.'::text),
(309633,34404,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sus cajas están en un montón. Yo creo que un cliente la ...'::text,'ayudará'::text,'va a ayudar'::text,NULL::text,'Sus cajas están en un montón. Yo creo que un cliente la ayudará.'::text),
(309632,34404,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ses boîtes sont en tas. Je pense qu''un client ...'::text,'l''aidera'::text,'va l''aider'::text,NULL::text,'Ses boîtes sont en tas. Je pense qu''un client l''aidera.'::text),
(309635,34404,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kutuları bir yığın halinde duruyor. Ben düşünüyorum ki bir müşteri ona ...'::text,'yardım edecek'::text,'yardım edecek'::text,NULL::text,'Kutuları bir yığın halinde duruyor. Ben düşünüyorum ki bir müşteri ona yardım edecek.'::text),
(309636,34404,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A dobozai egy kupacban hevernek. Én azt hiszem, egy vásárló ... neki.'::text,'segíteni fog'::text,'segíteni fog'::text,NULL::text,'A dobozai egy kupacban hevernek. Én azt hiszem, egy vásárló segíteni fog neki.'::text),
(309954,34440,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Flugzeug wirft drei ... an Fallschirmen ab.'::text,'Kisten'::text,'Kiste'::text,'Kisten'::text,'Das Flugzeug wirft drei Kisten an Fallschirmen ab.'::text),
(309958,34440,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Літак скидає три ... на парашутах.'::text,'ящики'::text,'ящик'::text,'ящики'::text,'Літак скидає три ящики на парашутах.'::text),
(309957,34440,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El avión lanza tres ... con paracaídas.'::text,'cajas'::text,'caja'::text,'cajas'::text,'El avión lanza tres cajas con paracaídas.'::text),
(309956,34440,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''avion largue trois ... avec des parachutes.'::text,'caisses'::text,'caisse'::text,'caisses'::text,'L''avion largue trois caisses avec des parachutes.'::text),
(309959,34440,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Uçak paraşütlerle üç ... atıyor.'::text,'sandık'::text,'sandık'::text,'sandıklar'::text,'Uçak paraşütlerle üç sandık atıyor.'::text),
(309960,34440,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A repülő három ... dob le ejtőernyővel.'::text,'ládát'::text,'ládát'::text,'ládát'::text,'A repülő három ládát dob le ejtőernyővel.'::text),
(309963,34441,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, da ... so fünf Kisten, die aus dem Flugzeug fallen, Digga.'::text,'sind'::text,'ist'::text,'sein'::text,'Yo, da sind so fünf Kisten, die aus dem Flugzeug fallen, Digga.'::text),
(309967,34441,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, там ... десь п''ять ящиків, що падають з того літака, бро.'::text,'є'::text,'є'::text,'бути'::text,'Йо, там є десь п''ять ящиків, що падають з того літака, бро.'::text),
(309966,34441,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ey, ... como cinco cajas cayendo de ese avión, tío.'::text,'hay'::text,'hay'::text,'hay'::text,'Ey, hay como cinco cajas cayendo de ese avión, tío.'::text),
(309965,34441,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, ... genre cinq caisses qui tombent de cet avion, frérot.'::text,'il y a'::text,'il y a'::text,'il y a'::text,'Yo, il y a genre cinq caisses qui tombent de cet avion, frérot.'::text),
(309968,34441,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o uçaktan düşen beş kadar sandık ..., bak.'::text,'var'::text,'var'::text,'olmak'::text,'Kanka, o uçaktan düşen beş kadar sandık var, bak.'::text),
(309969,34441,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, vagy öt láda ..., ami abból a gépből esik le, tesó.'::text,'van'::text,'van'::text,'lenni'::text,'Figyu, vagy öt láda van, ami abból a gépből esik le, tesó.'::text),
(313653,34851,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihr Dach ist ... Flachdach, kein Ziegeldach.'::text,'ein'::text,'das'::text,'ein'::text,'Ihr Dach ist ein Flachdach, kein Ziegeldach.'::text),
(313657,34851,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її дах — ... плаский дах, а не черепичний.'::text,''::text,NULL::text,NULL::text,'Її дах — плаский дах, а не черепичний.'::text),
(313656,34851,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su tejado es ... tejado plano, no un tejado de tejas.'::text,'un'::text,'el'::text,'un'::text,'Su tejado es un tejado plano, no un tejado de tejas.'::text),
(313655,34851,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son toit est ... toit plat, pas un toit en tuiles.'::text,'un'::text,'le'::text,'un'::text,'Son toit est un toit plat, pas un toit en tuiles.'::text),
(313658,34851,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onun çatısı ... düz çatı, kiremitli çatı değil.'::text,'bir'::text,NULL::text,'bir'::text,'Onun çatısı bir düz çatı, kiremitli çatı değil.'::text),
(313659,34851,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az ő teteje ... lapos tető, nem cseréptető.'::text,'egy'::text,'a'::text,'egy'::text,'Az ő teteje egy lapos tető, nem cseréptető.'::text),
(313689,34855,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, ihr gehen irgendwie die Klammern aus. Nur noch ... Klammern auf dem Dach.'::text,'ein paar'::text,'viel'::text,'ein bisschen'::text,'Digga, ihr gehen irgendwie die Klammern aus. Nur noch ein paar Klammern auf dem Dach.'::text),
(313693,34855,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, у неї якось закінчуються прищіпки. На даху лишилося лише ... прищіпок.'::text,'кілька'::text,'багато'::text,'трохи'::text,'Бро, у неї якось закінчуються прищіпки. На даху лишилося лише кілька прищіпок.'::text),
(313692,34855,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ella se está quedando sin pinzas. Solo quedan ... pinzas en la azotea.'::text,'unas pocas'::text,'mucha'::text,'un poco de'::text,'Tío, ella se está quedando sin pinzas. Solo quedan unas pocas pinzas en la azotea.'::text),
(313691,34855,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, elle est un peu à court de pinces. Il ne reste que ... pinces sur le toit.'::text,'quelques'::text,'beaucoup de'::text,'un peu de'::text,'Frérot, elle est un peu à court de pinces. Il ne reste que quelques pinces sur le toit.'::text),
(313694,34855,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o resmen mandalsız kalmak üzere. Çatıda sadece ... mandal kaldı.'::text,'birkaç'::text,'çok'::text,'biraz'::text,'Kanka, o resmen mandalsız kalmak üzere. Çatıda sadece birkaç mandal kaldı.'::text),
(313695,34855,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ő kicsit kifogyott a csipeszekből. Már csak ... csipesz maradt a tetőn.'::text,'pár'::text,'sok'::text,'egy kis'::text,'Tesó, ő kicsit kifogyott a csipeszekből. Már csak pár csipesz maradt a tetőn.'::text),
(304536,33838,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Starker Move: Du steckst die Decke in ... andere Maschine.'::text,'die'::text,'eine'::text,'eine'::text,'Starker Move: Du steckst die Decke in die andere Maschine.'::text),
(304540,33838,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Круто: ти кладеш ковдру в ... іншу машину.'::text,''::text,NULL::text,NULL::text,'Круто: ти кладеш ковдру в іншу машину.'::text),
(304539,33838,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Buen movimiento: tú metes la manta en ... otra máquina.'::text,'la'::text,'una'::text,'una'::text,'Buen movimiento: tú metes la manta en la otra máquina.'::text),
(304538,33838,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Joli coup : tu mets la couverture dans ... autre machine.'::text,'l'''::text,'une'::text,'une'::text,'Joli coup : tu mets la couverture dans l'' autre machine.'::text),
(304541,33838,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şık hareket: sen battaniyeyi ... diğer makineye koyuyorsun.'::text,''::text,'bir'::text,'bir'::text,'Şık hareket: sen battaniyeyi diğer makineye koyuyorsun.'::text),
(304542,33838,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ügyes húzás: te a takarót ... másik gépbe teszed.'::text,'a'::text,'egy'::text,'egy'::text,'Ügyes húzás: te a takarót a másik gépbe teszed.'::text),
(304599,33845,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gestern ... die Maschine die Decke, also war die Decke in der Maschine.'::text,'wusch'::text,'wäscht'::text,NULL::text,'Gestern wusch die Maschine die Decke, also war die Decke in der Maschine.'::text),
(304603,33845,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Учора машина ... ковдру, тож ковдра була в машині.'::text,'випрала'::text,'пере'::text,NULL::text,'Учора машина випрала ковдру, тож ковдра була в машині.'::text),
(304602,33845,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ayer la máquina ... la manta, así que la manta estaba en la máquina.'::text,'lavó'::text,'lava'::text,NULL::text,'Ayer la máquina lavó la manta, así que la manta estaba en la máquina.'::text),
(304601,33845,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hier, la machine ... la couverture, donc la couverture était dans la machine.'::text,'a lavé'::text,'lave'::text,NULL::text,'Hier, la machine a lavé la couverture, donc la couverture était dans la machine.'::text),
(304604,33845,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dün makine battaniyeyi ..., yani battaniye makinedeydi.'::text,'yıkadı'::text,'yıkar'::text,NULL::text,'Dün makine battaniyeyi yıkadı, yani battaniye makinedeydi.'::text),
(304605,33845,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tegnap a gép ... a takarót, tehát a takaró a gépben volt.'::text,'kimosta'::text,'kimossa'::text,NULL::text,'Tegnap a gép kimosta a takarót, tehát a takaró a gépben volt.'::text),
(326649,36295,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der schwache Mann ... gerade, eine riesige Hantel zu heben.'::text,'versucht'::text,'versucht'::text,'versucht'::text,'Der schwache Mann versucht gerade, eine riesige Hantel zu heben.'::text),
(326653,36295,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слабкий чоловік саме зараз ... підняти величезну гантель.'::text,'намагається'::text,'намагається'::text,'намагається'::text,'Слабкий чоловік саме зараз намагається підняти величезну гантель.'::text),
(326652,36295,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre débil ... levantar una mancuerna enorme ahora mismo.'::text,'está intentando'::text,'intenta'::text,'está intentando'::text,'El hombre débil está intentando levantar una mancuerna enorme ahora mismo.'::text),
(326651,36295,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme faible ... soulever un énorme haltère en ce moment.'::text,'est en train d''essayer de'::text,'essaie de'::text,'est en train d''essayer de'::text,'L''homme faible est en train d''essayer de soulever un énorme haltère en ce moment.'::text),
(326654,36295,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zayıf adam şu an kocaman bir dambılı kaldırmaya ...'::text,'çalışıyor'::text,'çalışır'::text,'çalışıyor'::text,'Zayıf adam şu an kocaman bir dambılı kaldırmaya çalışıyor.'::text),
(326655,36295,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gyenge férfi épp most ... felemelni egy hatalmas súlyzót.'::text,'próbál'::text,'próbál'::text,'próbál'::text,'A gyenge férfi épp most próbál felemelni egy hatalmas súlyzót.'::text),
(315444,35050,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er staubt ... Regale ab, weil es seine Regale sind.'::text,'seine'::text,'ihre'::text,'seine'::text,'Er staubt seine Regale ab, weil es seine Regale sind.'::text),
(315448,35050,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він витирає пил з ... полиць, бо це його полиці.'::text,'своїх'::text,'своїх'::text,'своїх'::text,'Він витирає пил з своїх полиць, бо це його полиці.'::text),
(315447,35050,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él limpia el polvo de ... estantes porque son sus estantes.'::text,'sus'::text,'sus'::text,'sus'::text,'Él limpia el polvo de sus estantes porque son sus estantes.'::text),
(315446,35050,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il dépoussière ... étagères parce que ce sont ses étagères.'::text,'ses'::text,'ses'::text,'ses'::text,'Il dépoussière ses étagères parce que ce sont ses étagères.'::text),
(315449,35050,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, ... raflarının tozunu alıyor çünkü onlar onun rafları.'::text,'onun'::text,'onun'::text,'onun'::text,'O, onun raflarının tozunu alıyor çünkü onlar onun rafları.'::text),
(315450,35050,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő leporolja a ..., mert azok az ő polcai.'::text,'polcait'::text,'polcait'::text,'polcait'::text,'Ő leporolja a polcait, mert azok az ő polcai.'::text),
(315480,35054,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tolle Arbeit, klar. Nur ein bisschen ... ist noch auf dem Regal.'::text,'Staub'::text,'Staub'::text,'Wolken'::text,'Tolle Arbeit, klar. Nur ein bisschen Staub ist noch auf dem Regal.'::text),
(315484,35054,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чудова робота, звісно. На полиці залишилося лише трохи ...'::text,'пилу'::text,'пилу'::text,'хмар'::text,'Чудова робота, звісно. На полиці залишилося лише трохи пилу.'::text),
(315483,35054,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Buen trabajo, obviamente. Solo queda un poco de ... en la estantería.'::text,'polvo'::text,'polvo'::text,'nubes'::text,'Buen trabajo, obviamente. Solo queda un poco de polvo en la estantería.'::text),
(315482,35054,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beau travail, évidemment. Il ne reste qu''un peu de ... sur l''étagère.'::text,'poussière'::text,'poussière'::text,'nuages'::text,'Beau travail, évidemment. Il ne reste qu''un peu de poussière sur l''étagère.'::text),
(315485,35054,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Harika iş, belli ki. Rafta sadece biraz ... kaldı.'::text,'toz'::text,'tozlar'::text,'bulutlar'::text,'Harika iş, belli ki. Rafta sadece biraz toz kaldı.'::text),
(315486,35054,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szép munka, nyilván. Már csak egy kis ... maradt a polcon.'::text,'por'::text,'por'::text,'felhő'::text,'Szép munka, nyilván. Már csak egy kis por maradt a polcon.'::text),
(324129,36015,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Diese Stadt ... eine riesige Käsetradition! Absolut der beste Tag!'::text,'hat'::text,'haben'::text,'hat'::text,'Diese Stadt hat eine riesige Käsetradition! Absolut der beste Tag!'::text),
(324133,36015,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Це місто ... величезну сирну традицію! Однозначно найкращий день!'::text,'має'::text,'мати'::text,'має'::text,'Це місто має величезну сирну традицію! Однозначно найкращий день!'::text),
(324132,36015,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Este pueblo ... una enorme tradición quesera! ¡Sin duda el mejor día!'::text,'tiene'::text,'tienen'::text,'tiene'::text,'¡Este pueblo tiene una enorme tradición quesera! ¡Sin duda el mejor día!'::text),
(324131,36015,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cette ville ... une énorme tradition du fromage ! Clairement le meilleur jour !'::text,'a'::text,'ont'::text,'a'::text,'Cette ville a une énorme tradition du fromage ! Clairement le meilleur jour !'::text),
(324134,36015,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu kasabanın devasa bir peynir geleneği ...! Kesinlikle en güzel gün!'::text,'var'::text,'var'::text,'var'::text,'Bu kasabanın devasa bir peynir geleneği var! Kesinlikle en güzel gün!'::text),
(324135,36015,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ennek a városnak hatalmas sajthagyománya ...! Abszolút a legjobb nap!'::text,'van'::text,'van'::text,'van'::text,'Ennek a városnak hatalmas sajthagyománya van! Abszolút a legjobb nap!'::text),
(324192,36022,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Den Käse zu tragen ist ein Albtraum, ... die Tradition geht weiter!'::text,'aber'::text,'also'::text,'weil'::text,'Den Käse zu tragen ist ein Albtraum, aber die Tradition geht weiter!'::text),
(324196,36022,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Носити цей сир — жах, ... традиція триває!'::text,'але'::text,'тому'::text,'бо'::text,'Носити цей сир — жах, але традиція триває!'::text),
(324195,36022,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Cargar el queso es una pesadilla, ... la tradición sigue!'::text,'pero'::text,'así que'::text,'porque'::text,'¡Cargar el queso es una pesadilla, pero la tradición sigue!'::text),
(324194,36022,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Porter le fromage, c''est un cauchemar, ... la tradition continue !'::text,'mais'::text,'donc'::text,'parce que'::text,'Porter le fromage, c''est un cauchemar, mais la tradition continue !'::text),
(324197,36022,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Peyniri taşımak kâbus, ... gelenek devam ediyor!'::text,'ama'::text,'bu yüzden'::text,'çünkü'::text,'Peyniri taşımak kâbus, ama gelenek devam ediyor!'::text),
(324198,36022,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sajtot cipelni rémálom, ... a hagyomány folytatódik!'::text,'de'::text,'ezért'::text,'mert'::text,'A sajtot cipelni rémálom, de a hagyomány folytatódik!'::text),
(302727,33637,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Albtraum! Ihre Tasche ist so klein, und sie ... zehn Lampen kaufen!'::text,'wird'::text,'wird'::text,'kauft'::text,'Albtraum! Ihre Tasche ist so klein, und sie wird zehn Lampen kaufen!'::text),
(302731,33637,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жах! Її сумка така маленька, а вона ... десять ламп!'::text,'збирається купити'::text,'купить'::text,'купує'::text,'Жах! Її сумка така маленька, а вона збирається купити десять ламп!'::text),
(302730,33637,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Pesadilla! ¡Su bolso es tan pequeño y ella ... diez lámparas!'::text,'va a comprar'::text,'comprará'::text,'compra'::text,'¡Pesadilla! ¡Su bolso es tan pequeño y ella va a comprar diez lámparas!'::text),
(302729,33637,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cauchemar ! Son sac est si petit, et elle ... dix lampes !'::text,'va acheter'::text,'achètera'::text,'achète'::text,'Cauchemar ! Son sac est si petit, et elle va acheter dix lampes !'::text),
(302732,33637,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kâbus! Çantası çok küçük ve o on lamba ...!'::text,'alacak'::text,'alacak'::text,'alır'::text,'Kâbus! Çantası çok küçük ve o on lamba alacak!'::text),
(302733,33637,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rémálom! A táskája olyan kicsi, és ő tíz lámpát ...!'::text,'fog venni'::text,'fog venni'::text,'vesz'::text,'Rémálom! A táskája olyan kicsi, és ő tíz lámpát fog venni!'::text),
(313014,34780,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, überall ... Theke sind Reiskörner, das gibt ein Chaos.'::text,'auf der'::text,'in der'::text,'an der'::text,'Alter, überall auf der Theke sind Reiskörner, das gibt ein Chaos.'::text),
(313018,34780,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, рисинки всюди ... прилавку, буде безлад.'::text,'на'::text,'у'::text,'біля'::text,'Чувак, рисинки всюди на прилавку, буде безлад.'::text),
(313017,34780,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, los granos de arroz están ... todo el mostrador, va a ser un desastre.'::text,'por'::text,'en'::text,'a'::text,'Tío, los granos de arroz están por todo el mostrador, va a ser un desastre.'::text),
(313016,34780,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, il y a des grains de riz partout ... le comptoir, ça va être le bazar.'::text,'sur'::text,'dans'::text,'à'::text,'Mec, il y a des grains de riz partout sur le comptoir, ça va être le bazar.'::text),
(313019,34780,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, pirinç taneleri tezgâhın ... her yerde, ortalık batacak.'::text,'üstünde'::text,'içinde'::text,NULL::text,'Kanka, pirinç taneleri tezgâhın üstünde her yerde, ortalık batacak.'::text),
(313020,34780,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Haver, a rizsszemek mindenhol ott vannak a ..., kosz lesz.'::text,'pulton'::text,'pultban'::text,'pultnál'::text,'Haver, a rizsszemek mindenhol ott vannak a pulton, kosz lesz.'::text),
(313050,34784,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ich diesen scharfen Reis esse, ... ich für immer weinen!'::text,'werde'::text,'bin'::text,NULL::text,'Wenn ich diesen scharfen Reis esse, werde ich für immer weinen!'::text),
(313054,34784,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо я з''їм цей гострий рис, я ... плакати вічно!'::text,'буду'::text,'є'::text,NULL::text,'Якщо я з''їм цей гострий рис, я буду плакати вічно!'::text),
(313053,34784,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si me como este arroz picante, yo ... llorar para siempre!'::text,''::text,'estoy'::text,NULL::text,'¡Si me como este arroz picante, yo llorar para siempre!'::text),
(313052,34784,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si je mange ce riz épicé, je ... pleurer pour toujours !'::text,''::text,'suis'::text,NULL::text,'Si je mange ce riz épicé, je pleurer pour toujours !'::text),
(313055,34784,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu acı pilavı yersem, ben sonsuza dek ...!'::text,'ağlayacağım'::text,NULL::text,NULL::text,'Bu acı pilavı yersem, ben sonsuza dek ağlayacağım!'::text),
(313056,34784,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha megeszem ezt a csípős rizst, én örökké sírni ...!'::text,'fogok'::text,'vagyok'::text,NULL::text,'Ha megeszem ezt a csípős rizst, én örökké sírni fogok!'::text),
(312645,34739,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er repariert normalerweise Autos, aber heute ... er einen Sicherungskasten.'::text,'repariert'::text,'repariert'::text,NULL::text,'Er repariert normalerweise Autos, aber heute repariert er einen Sicherungskasten.'::text),
(312649,34739,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він зазвичай ремонтує машини, але сьогодні ... електрощиток.'::text,'ремонтує'::text,'ремонтує'::text,NULL::text,'Він зазвичай ремонтує машини, але сьогодні ремонтує електрощиток.'::text),
(312648,34739,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él normalmente repara coches, pero hoy ... una caja de fusibles.'::text,'está reparando'::text,'repara'::text,NULL::text,'Él normalmente repara coches, pero hoy está reparando una caja de fusibles.'::text),
(312647,34739,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il répare d''habitude des voitures, mais aujourd''hui il ... un tableau électrique.'::text,'est en train de réparer'::text,'répare'::text,NULL::text,'Il répare d''habitude des voitures, mais aujourd''hui il est en train de réparer un tableau électrique.'::text),
(312650,34739,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O genelde araba tamir eder ama bugün bir sigorta kutusu ...'::text,'tamir ediyor'::text,'tamir eder'::text,NULL::text,'O genelde araba tamir eder ama bugün bir sigorta kutusu tamir ediyor.'::text),
(312651,34739,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő általában autókat javít, de ma egy biztosítékdobozt ...'::text,'javít'::text,'javít'::text,NULL::text,'Ő általában autókat javít, de ma egy biztosítékdobozt javít.'::text),
(312564,34730,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Reparatur-Roadmap: Sie ... heute Abend 3 Sicherungsautomaten reparieren.'::text,'wird'::text,'wird'::text,'ist'::text,'Reparatur-Roadmap: Sie wird heute Abend 3 Sicherungsautomaten reparieren.'::text),
(312568,34730,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Роадмап ремонту: вона ... полагодити 3 автомати сьогодні ввечері.'::text,'збирається'::text,'буде'::text,'є'::text,'Роадмап ремонту: вона збирається полагодити 3 автомати сьогодні ввечері.'::text),
(312567,34730,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hoja de ruta de la reparación: ella ... arreglar 3 disyuntores esta noche.'::text,'va a'::text,NULL::text,'está'::text,'Hoja de ruta de la reparación: ella va a arreglar 3 disyuntores esta noche.'::text),
(312566,34730,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Feuille de route de la réparation : elle ... réparer 3 disjoncteurs ce soir.'::text,'va'::text,NULL::text,'est'::text,'Feuille de route de la réparation : elle va réparer 3 disjoncteurs ce soir.'::text),
(312569,34730,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onarım yol haritası: o bu akşam 3 sigortayı ...'::text,'onaracak'::text,'onaracak'::text,NULL::text,'Onarım yol haritası: o bu akşam 3 sigortayı onaracak.'::text),
(312570,34730,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Javítási ütemterv: ő ma este 3 kismegszakítót ... megjavítani.'::text,'fog'::text,'fog'::text,'van'::text,'Javítási ütemterv: ő ma este 3 kismegszakítót fog megjavítani.'::text),
(310962,34552,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... die Produkte im Regal in einer Reihe.'::text,'stellt'::text,'stellen'::text,'stellend'::text,'Er stellt die Produkte im Regal in einer Reihe.'::text),
(310966,34552,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... товари на полиці.'::text,'вишиковує'::text,'вишиковувати'::text,'вишиковуючи'::text,'Він вишиковує товари на полиці.'::text),
(310965,34552,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... los productos en la estantería.'::text,'alinea'::text,'alinear'::text,'alineando'::text,'Él alinea los productos en la estantería.'::text),
(310964,34552,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... les produits sur l''étagère.'::text,'aligne'::text,'aligner'::text,'alignant'::text,'Il aligne les produits sur l''étagère.'::text),
(310967,34552,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O ürünleri rafa ...'::text,'dizer'::text,'dizmek'::text,'dizerek'::text,'O ürünleri rafa dizer.'::text),
(310968,34552,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő ... a termékeket a polcon.'::text,'sorba rendezi'::text,'sorba rendezni'::text,'sorba rendező'::text,'Ő sorba rendezi a termékeket a polcon.'::text),
(311007,34557,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Deine Produktreihen sind perfekt. Ehrlich, du ... diesen Laden leiten.'::text,'solltest'::text,'sollst'::text,'solltest'::text,'Deine Produktreihen sind perfekt. Ehrlich, du solltest diesen Laden leiten.'::text),
(311011,34557,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Твої ряди товарів ідеальні. Чесно, ти ... керувати цим магазином.'::text,'мав би'::text,'будеш'::text,'мав би'::text,'Твої ряди товарів ідеальні. Чесно, ти мав би керувати цим магазином.'::text),
(311010,34557,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tus filas de productos son perfectas. En serio, tú ... dirigir esta tienda.'::text,'deberías'::text,'deberás'::text,'deberías'::text,'Tus filas de productos son perfectas. En serio, tú deberías dirigir esta tienda.'::text),
(311009,34557,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tes rangées de produits sont parfaites. Franchement, tu ... diriger ce magasin.'::text,'devrais'::text,'devras'::text,'devrais'::text,'Tes rangées de produits sont parfaites. Franchement, tu devrais diriger ce magasin.'::text),
(311012,34557,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ürün sıraların kusursuz. Açıkçası sen bu dükkânı ...'::text,'işletmelisin'::text,'işleteceksin'::text,'işletmelisin'::text,'Ürün sıraların kusursuz. Açıkçası sen bu dükkânı işletmelisin.'::text),
(311013,34557,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tökéletesek a termék-soraid. Őszintén, neked ... vezetned ezt a boltot.'::text,'kellene'::text,'kell'::text,'kellene'::text,'Tökéletesek a termék-soraid. Őszintén, neked kellene vezetned ezt a boltot.'::text),
(319161,35463,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sein Start so schnell ist, ... er das Rennen gewinnen.'::text,'wird'::text,'gewinnen'::text,'gewann'::text,'Wenn sein Start so schnell ist, wird er das Rennen gewinnen.'::text),
(319165,35463,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо його старт такий швидкий, він ... перегони.'::text,'виграє'::text,'вигравати'::text,'виграв'::text,'Якщо його старт такий швидкий, він виграє перегони.'::text),
(319164,35463,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si su salida es así de rápida, él ... la carrera.'::text,'ganará'::text,'ganar'::text,'ganó'::text,'Si su salida es así de rápida, él ganará la carrera.'::text),
(319163,35463,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si son départ est aussi rapide, il ... la course.'::text,'gagnera'::text,'gagner'::text,'a gagné'::text,'Si son départ est aussi rapide, il gagnera la course.'::text),
(319166,35463,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çıkışı bu kadar hızlıysa, o yarışı ...'::text,'kazanacak'::text,'kazanmak'::text,'kazandı'::text,'Çıkışı bu kadar hızlıysa, o yarışı kazanacak.'::text),
(319167,35463,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha ilyen gyors a rajtja, ő ... a versenyt.'::text,'meg fogja nyerni'::text,'megnyerni'::text,'megnyerte'::text,'Ha ilyen gyors a rajtja, ő meg fogja nyerni a versenyt.'::text),
(313878,34876,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jede Welle ... deine Burg, aber du bist so ruhig. Respekt.'::text,'zerstört'::text,'zerstören'::text,'zerstörend'::text,'Jede Welle zerstört deine Burg, aber du bist so ruhig. Respekt.'::text),
(313882,34876,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кожна хвиля ... твій замок, а ти такий спокійний. Респект.'::text,'руйнує'::text,'руйнувати'::text,'руйнуючи'::text,'Кожна хвиля руйнує твій замок, а ти такий спокійний. Респект.'::text),
(313881,34876,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cada ola ... tu castillo, pero tú estás tan tranquilo. Respeto.'::text,'destruye'::text,'destruir'::text,'destruyendo'::text,'Cada ola destruye tu castillo, pero tú estás tan tranquilo. Respeto.'::text),
(313880,34876,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Chaque vague ... ton château, mais tu es si calme. Respect.'::text,'détruit'::text,'détruire'::text,'détruisant'::text,'Chaque vague détruit ton château, mais tu es si calme. Respect.'::text),
(313883,34876,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her dalga kaleni ... ama sen çok sakinsin. Saygı.'::text,'yıkar'::text,'yıkmak'::text,'yıkarak'::text,'Her dalga kaleni yıkar ama sen çok sakinsin. Saygı.'::text),
(313884,34876,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minden hullám ... a váradat, de te olyan nyugodt vagy. Respekt.'::text,'lerombolja'::text,'lerombolni'::text,'leromboló'::text,'Minden hullám lerombolja a váradat, de te olyan nyugodt vagy. Respekt.'::text),
(313905,34879,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vor einer Stunde ... die Wellen seine hohe Sandburg.'::text,'zerstörten'::text,'zerstört'::text,'zerstören'::text,'Vor einer Stunde zerstörten die Wellen seine hohe Sandburg.'::text),
(313909,34879,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Годину тому хвилі ... його високий замок із піску.'::text,'зруйнували'::text,'руйнує'::text,'руйнують'::text,'Годину тому хвилі зруйнували його високий замок із піску.'::text),
(313908,34879,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hace una hora las olas ... su alto castillo de arena.'::text,'destruyeron'::text,'destruye'::text,'destruyen'::text,'Hace una hora las olas destruyeron su alto castillo de arena.'::text),
(313907,34879,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il y a une heure, les vagues ... son grand château de sable.'::text,'ont détruit'::text,'détruit'::text,'détruisent'::text,'Il y a une heure, les vagues ont détruit son grand château de sable.'::text),
(313910,34879,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir saat önce dalgalar onun yüksek kumdan kalesini ...'::text,'yıktı'::text,'yıkar'::text,'yıkarlar'::text,'Bir saat önce dalgalar onun yüksek kumdan kalesini yıktı.'::text),
(313911,34879,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy órája a hullámok ... a magas homokvárát.'::text,'lerombolták'::text,'lerombolja'::text,'lerombolják'::text,'Egy órája a hullámok lerombolták a magas homokvárát.'::text),
(298920,33214,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Dampf verdeckt sein Gesicht, aber nicht ... Pelzmütze.'::text,'seine'::text,'ihre'::text,'seine'::text,'Der Dampf verdeckt sein Gesicht, aber nicht seine Pelzmütze.'::text),
(298924,33214,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Пара ховає його обличчя, але не ... хутряну шапку.'::text,'його'::text,'її'::text,'його'::text,'Пара ховає його обличчя, але не його хутряну шапку.'::text),
(298923,33214,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El vapor le tapa la cara, pero no ... gorro de piel.'::text,'su'::text,'su'::text,'su'::text,'El vapor le tapa la cara, pero no su gorro de piel.'::text),
(298922,33214,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La vapeur cache son visage, mais pas ... chapka.'::text,'sa'::text,'sa'::text,'sa'::text,'La vapeur cache son visage, mais pas sa chapka.'::text),
(298925,33214,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Buhar onun yüzünü gizliyor ama ... kürk şapkasını değil.'::text,'onun'::text,'onun'::text,'onun'::text,'Buhar onun yüzünü gizliyor ama onun kürk şapkasını değil.'::text),
(298926,33214,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gőz eltakarja az arcát, de a ... nem.'::text,'szőrmesapkáját'::text,'szőrmesapkáját'::text,'szőrmesapkáját'::text,'A gőz eltakarja az arcát, de a szőrmesapkáját nem.'::text),
(298965,33219,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tolle Wahl, klar. Jeden Tag ... er in der Sauna eine Pelzmütze.'::text,'trägt'::text,'trug'::text,NULL::text,'Tolle Wahl, klar. Jeden Tag trägt er in der Sauna eine Pelzmütze.'::text),
(298969,33219,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чудовий вибір, звісно. Щодня він ... хутряну шапку в сауні.'::text,'носить'::text,'носив'::text,NULL::text,'Чудовий вибір, звісно. Щодня він носить хутряну шапку в сауні.'::text),
(298968,33219,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gran elección, obviamente. Cada día él ... un gorro de piel en la sauna.'::text,'lleva'::text,'llevó'::text,NULL::text,'Gran elección, obviamente. Cada día él lleva un gorro de piel en la sauna.'::text),
(298967,33219,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Excellent choix, évidemment. Tous les jours, il ... une chapka dans le sauna.'::text,'porte'::text,'a porté'::text,NULL::text,'Excellent choix, évidemment. Tous les jours, il porte une chapka dans le sauna.'::text),
(298970,33219,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Harika seçim, belli ki. O her gün saunada kürk şapka ...'::text,'takar'::text,'taktı'::text,NULL::text,'Harika seçim, belli ki. O her gün saunada kürk şapka takar.'::text),
(298971,33219,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Remek választás, nyilván. Ő minden nap szőrmesapkát ... a szaunában.'::text,'hord'::text,'hordott'::text,NULL::text,'Remek választás, nyilván. Ő minden nap szőrmesapkát hord a szaunában.'::text),
(308541,34283,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Krankenschwester untersucht ... Patienten auf dem Schulfest.'::text,'viele'::text,'viel'::text,'ein bisschen'::text,'Die Krankenschwester untersucht viele Patienten auf dem Schulfest.'::text),
(308545,34283,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Медсестра оглядає ... пацієнтів на шкільному ярмарку.'::text,'багато'::text,'багато'::text,'трохи'::text,'Медсестра оглядає багато пацієнтів на шкільному ярмарку.'::text),
(308544,34283,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La enfermera revisa a ... pacientes en la feria del colegio.'::text,'muchos'::text,'mucho'::text,'un poco de'::text,'La enfermera revisa a muchos pacientes en la feria del colegio.'::text),
(308543,34283,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''infirmière examine ... patients à la fête de l''école.'::text,'beaucoup de'::text,'beaucoup de'::text,'un peu de'::text,'L''infirmière examine beaucoup de patients à la fête de l''école.'::text),
(308546,34283,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hemşire okul şenliğinde ... hastayı muayene ediyor.'::text,'çok'::text,'çok'::text,'biraz'::text,'Hemşire okul şenliğinde çok hastayı muayene ediyor.'::text),
(308547,34283,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az ápolónő ... beteget vizsgál meg az iskolai vásáron.'::text,'sok'::text,'sok'::text,'egy kis'::text,'Az ápolónő sok beteget vizsgál meg az iskolai vásáron.'::text),
(297732,33082,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... mit seiner Gruppe vor dem Wasserfall.'::text,'steht'::text,'stehen'::text,'stehend'::text,'Er steht mit seiner Gruppe vor dem Wasserfall.'::text),
(297736,33082,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... зі своєю групою перед водоспадом.'::text,'стоїть'::text,'стояти'::text,'стоячи'::text,'Він стоїть зі своєю групою перед водоспадом.'::text),
(297735,33082,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... con su grupo delante de la cascada.'::text,'está de pie'::text,'estar de pie'::text,'estando de pie'::text,'Él está de pie con su grupo delante de la cascada.'::text),
(297734,33082,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... avec son groupe devant la cascade.'::text,'se tient'::text,'se tenir'::text,'se tenant'::text,'Il se tient avec son groupe devant la cascade.'::text),
(297737,33082,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O grubuyla şelalenin önünde ...'::text,'durur'::text,'durmak'::text,'durarak'::text,'O grubuyla şelalenin önünde durur.'::text),
(297738,33082,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő a csoportjával ... a vízesés előtt.'::text,'áll'::text,'állni'::text,'álló'::text,'Ő a csoportjával áll a vízesés előtt.'::text),
(297786,33088,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt: Du bist müde, ... du jubelst trotzdem am lautesten in der Gruppe.'::text,'aber'::text,'also'::text,'weil'::text,'Respekt: Du bist müde, aber du jubelst trotzdem am lautesten in der Gruppe.'::text),
(297790,33088,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Респект: ти втомлений, ... все одно вболіваєш найгучніше в групі.'::text,'але'::text,'тому'::text,'бо'::text,'Респект: ти втомлений, але все одно вболіваєш найгучніше в групі.'::text),
(297789,33088,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respeto: tú estás cansado, ... aun así animas más fuerte que nadie del grupo.'::text,'pero'::text,'así que'::text,'porque'::text,'Respeto: tú estás cansado, pero aun así animas más fuerte que nadie del grupo.'::text),
(297788,33088,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respect : tu es fatigué, ... tu encourages quand même le plus fort du groupe.'::text,'mais'::text,'donc'::text,'parce que'::text,'Respect : tu es fatigué, mais tu encourages quand même le plus fort du groupe.'::text),
(297791,33088,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saygı: sen yorgunsun ... yine de grupta en yüksek sesle tezahürat yapıyorsun.'::text,'ama'::text,'bu yüzden'::text,'çünkü'::text,'Saygı: sen yorgunsun ama yine de grupta en yüksek sesle tezahürat yapıyorsun.'::text),
(297792,33088,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt: te fáradt vagy, ... mégis a leghangosabban szurkolsz a csoportban.'::text,'de'::text,'ezért'::text,'mert'::text,'Respekt: te fáradt vagy, de mégis a leghangosabban szurkolsz a csoportban.'::text),
(326577,36287,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Wassermelone hat vierzig ..., also hat sie vierzig.'::text,'Gummibänder'::text,'Gummiband'::text,'Gummibänder'::text,'Die Wassermelone hat vierzig Gummibänder, also hat sie vierzig.'::text),
(326581,36287,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кавун має сорок ..., тож у нього їх сорок.'::text,'гумок'::text,'гумка'::text,'гумок'::text,'Кавун має сорок гумок, тож у нього їх сорок.'::text),
(326580,36287,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La sandía tiene cuarenta ..., así que tiene cuarenta.'::text,'gomas'::text,'goma'::text,'gomas'::text,'La sandía tiene cuarenta gomas, así que tiene cuarenta.'::text),
(326579,36287,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La pastèque a quarante ..., donc elle en a quarante.'::text,'élastiques'::text,'élastique'::text,'élastiques'::text,'La pastèque a quarante élastiques, donc elle en a quarante.'::text),
(326582,36287,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Karpuzun kırk lastik ... var, yani kırk tane var.'::text,'bant'::text,'bant'::text,'bantlar'::text,'Karpuzun kırk lastik bant var, yani kırk tane var.'::text),
(326583,36287,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A görögdinnyén negyven ... van, tehát negyven van rajta.'::text,'gumi'::text,'gumi'::text,'gumi'::text,'A görögdinnyén negyven gumi van, tehát negyven van rajta.'::text),
(326631,36293,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, da ist so viel ... von der Melone im Gras. Kult.'::text,'Saft'::text,'Saft'::text,'Kerne'::text,'Digga, da ist so viel Saft von der Melone im Gras. Kult.'::text),
(326635,36293,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, на траві стільки кавунового ... Культово.'::text,'соку'::text,'соку'::text,'насіння'::text,'Бро, на траві стільки кавунового соку Культово.'::text),
(326634,36293,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, hay tanto ... de sandía en la hierba. Icónico.'::text,'zumo'::text,'zumo'::text,'semillas'::text,'Tío, hay tanto zumo de sandía en la hierba. Icónico.'::text),
(326633,36293,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, il y a tellement de ... de pastèque sur l''herbe. Iconique.'::text,'jus'::text,'jus'::text,'pépins'::text,'Frérot, il y a tellement de jus de pastèque sur l''herbe. Iconique.'::text),
(326636,36293,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, çimlerde o kadar çok karpuz ... var ki. Efsane.'::text,'suyu'::text,'suları'::text,'çekirdeği'::text,'Kanka, çimlerde o kadar çok karpuz suyu var ki. Efsane.'::text),
(326637,36293,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, annyi ... van a füvön a dinnyéből. Ikonikus.'::text,'lé'::text,'lé'::text,'mag'::text,'Tesó, annyi lé van a füvön a dinnyéből. Ikonikus.'::text),
(296157,32907,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihre Gesichter im Handy ... sehr lustig.'::text,'sind'::text,'ist'::text,'bin'::text,'Ihre Gesichter im Handy sind sehr lustig.'::text),
(296161,32907,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Їхні обличчя в телефоні ... дуже смішні.'::text,'є'::text,'є'::text,'є'::text,'Їхні обличчя в телефоні є дуже смішні.'::text),
(296160,32907,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sus caras en el móvil ... muy graciosas.'::text,'son'::text,'es'::text,'soy'::text,'Sus caras en el móvil son muy graciosas.'::text),
(296159,32907,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Leurs têtes dans le téléphone ... très drôles.'::text,'sont'::text,'est'::text,'suis'::text,'Leurs têtes dans le téléphone sont très drôles.'::text),
(296162,32907,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Telefondaki yüzleri çok komik ...'::text,''::text,NULL::text,NULL::text,'Telefondaki yüzleri çok komik.'::text),
(296163,32907,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az arcuk a telefonban ... nagyon vicces.'::text,''::text,NULL::text,'vagyok'::text,'Az arcuk a telefonban nagyon vicces.'::text),
(296184,32910,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, anscheinend ... sie jeden einzelnen Tag im Unterricht Grimassen.'::text,'schneiden'::text,'schnitten'::text,NULL::text,'Hör zu, anscheinend schneiden sie jeden einzelnen Tag im Unterricht Grimassen.'::text),
(296188,32910,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, вони ... смішні гримаси на уроці кожнісінький день.'::text,'корчать'::text,'корчили'::text,NULL::text,'Слухай, кажуть, вони корчать смішні гримаси на уроці кожнісінький день.'::text),
(296187,32910,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, al parecer ellos ... muecas graciosas en clase todos los días.'::text,'hacen'::text,'hicieron'::text,NULL::text,'Oye, al parecer ellos hacen muecas graciosas en clase todos los días.'::text),
(296186,32910,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment ils ... des grimaces en classe tous les jours.'::text,'font'::text,'ont fait'::text,NULL::text,'Écoute, apparemment ils font des grimaces en classe tous les jours.'::text),
(296189,32910,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, görünüşe göre onlar her gün sınıfta komik suratlar ...'::text,'yapar'::text,'yaptı'::text,NULL::text,'Dinle, görünüşe göre onlar her gün sınıfta komik suratlar yapar.'::text),
(296190,32910,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag ők minden egyes nap vicces fejeket ... az órán.'::text,'vágnak'::text,'vágtak'::text,NULL::text,'Figyelj, állítólag ők minden egyes nap vicces fejeket vágnak az órán.'::text),
(320961,35663,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mehrere Frauen ... auf der Party dunkle Sonnenbrillen auf.'::text,'haben'::text,'hat'::text,'haben'::text,'Mehrere Frauen haben auf der Party dunkle Sonnenbrillen auf.'::text),
(320965,35663,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кілька жінок ... на вечірці темні сонцезахисні окуляри.'::text,'мають'::text,'має'::text,'мають'::text,'Кілька жінок мають на вечірці темні сонцезахисні окуляри.'::text),
(320964,35663,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Varias mujeres ... gafas de sol oscuras puestas en la fiesta.'::text,'tienen'::text,'tiene'::text,'tienen'::text,'Varias mujeres tienen gafas de sol oscuras puestas en la fiesta.'::text),
(320963,35663,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Plusieurs femmes ... des lunettes de soleil foncées sur le nez à la fête.'::text,'ont'::text,'a'::text,'ont'::text,'Plusieurs femmes ont des lunettes de soleil foncées sur le nez à la fête.'::text),
(320966,35663,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Partide birkaç kadının gözünde koyu güneş gözlüğü ...'::text,'var'::text,'var'::text,'var'::text,'Partide birkaç kadının gözünde koyu güneş gözlüğü var.'::text),
(320967,35663,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A bulin több nőn sötét napszemüveg ...'::text,'van'::text,'van'::text,'van'::text,'A bulin több nőn sötét napszemüveg van.'::text),
(320988,35666,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich gesagt, ... Gäste hier lieben deine Sonnenbrille.'::text,'viele'::text,'viel'::text,'ein bisschen'::text,'Ehrlich gesagt, viele Gäste hier lieben deine Sonnenbrille.'::text),
(320992,35666,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ... гостей тут у захваті від твоїх сонцезахисних окулярів.'::text,'багато'::text,'багато'::text,'трохи'::text,'Чесно, багато гостей тут у захваті від твоїх сонцезахисних окулярів.'::text),
(320991,35666,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No te voy a mentir, a ... invitados de aquí les encantan tus gafas de sol.'::text,'muchos'::text,'mucho'::text,'un poco de'::text,'No te voy a mentir, a muchos invitados de aquí les encantan tus gafas de sol.'::text),
(320990,35666,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sans mentir, ... invités ici adorent tes lunettes de soleil.'::text,'beaucoup d'''::text,'beaucoup d'''::text,'un peu d'''::text,'Sans mentir, beaucoup d'' invités ici adorent tes lunettes de soleil.'::text),
(320993,35666,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, buradaki ... misafir güneş gözlüklerine bayılıyor.'::text,'çok'::text,'çok'::text,'biraz'::text,'Yalan yok, buradaki çok misafir güneş gözlüklerine bayılıyor.'::text),
(320994,35666,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hazudok, itt ... vendég imádja a napszemüvegedet.'::text,'sok'::text,'sok'::text,'egy kis'::text,'Nem hazudok, itt sok vendég imádja a napszemüvegedet.'::text),
(303042,33672,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... mit geschlossenen Augen in der Schaumstoffgrube.'::text,'lacht'::text,'lachen'::text,'lachend'::text,'Sie lacht mit geschlossenen Augen in der Schaumstoffgrube.'::text),
(303046,33672,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... в поролоновій ямі із заплющеними очима.'::text,'сміється'::text,'сміятися'::text,'сміючись'::text,'Вона сміється в поролоновій ямі із заплющеними очима.'::text),
(303045,33672,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... en el foso de espuma con los ojos cerrados.'::text,'ríe'::text,'reír'::text,'riendo'::text,'Ella ríe en el foso de espuma con los ojos cerrados.'::text),
(303044,33672,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... dans la fosse à mousse, les yeux fermés.'::text,'rit'::text,'rire'::text,'riant'::text,'Elle rit dans la fosse à mousse, les yeux fermés.'::text),
(303047,33672,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O köpük havuzunda gözleri kapalı ...'::text,'güler'::text,'gülmek'::text,'gülerek'::text,'O köpük havuzunda gözleri kapalı güler.'::text),
(303048,33672,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő csukott szemmel ... a szivacsmedencében.'::text,'nevet'::text,'nevetni'::text,'nevető'::text,'Ő csukott szemmel nevet a szivacsmedencében.'::text),
(303105,33679,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du lachst so sehr, ... die Schaumstoffgrube Spaß macht. Ehrlich, ikonisch.'::text,'weil'::text,'aber'::text,'also'::text,'Du lachst so sehr, weil die Schaumstoffgrube Spaß macht. Ehrlich, ikonisch.'::text),
(303109,33679,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти так сильно смієшся, ... поролонова яма — це весело. Чесно, культово.'::text,'бо'::text,'але'::text,'тому'::text,'Ти так сильно смієшся, бо поролонова яма — це весело. Чесно, культово.'::text),
