(320367,35597,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Leistungsbeurteilung: Sie schwingt die 20-kg-Kettlebell ...'::text,'kraftvoll'::text,'kraftvoll'::text,'Kraft'::text,'Leistungsbeurteilung: Sie schwingt die 20-kg-Kettlebell kraftvoll.'::text),
(320371,35597,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Оцінка результатів: вона махає гирею на 20 кг ...'::text,'сильно'::text,'сильний'::text,'сила'::text,'Оцінка результатів: вона махає гирею на 20 кг сильно.'::text),
(320370,35597,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Evaluación de desempeño: ella balancea la pesa rusa de 20 kg ...'::text,'fuertemente'::text,'fuerte'::text,'fuerza'::text,'Evaluación de desempeño: ella balancea la pesa rusa de 20 kg fuertemente.'::text),
(320369,35597,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Évaluation de performance : elle balance le kettlebell de 20 kg ...'::text,'fortement'::text,'fort'::text,'force'::text,'Évaluation de performance : elle balance le kettlebell de 20 kg fortement.'::text),
(320372,35597,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Performans değerlendirmesi: o 20 kiloluk kettlebell''i ... sallıyor.'::text,'güçlüce'::text,'güçlü'::text,'güçlülük'::text,'Performans değerlendirmesi: o 20 kiloluk kettlebell''i güçlüce sallıyor.'::text),
(320373,35597,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Teljesítményértékelés: ő ... lendíti a 20 kilós kettlebellt.'::text,'erősen'::text,'erős'::text,'erősség'::text,'Teljesítményértékelés: ő erősen lendíti a 20 kilós kettlebellt.'::text),
(312303,34701,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... entspannen sie sich? Auf dem Wasser eines Salzsees.'::text,'Wo'::text,'Wann'::text,'Wer'::text,'Wo entspannen sie sich? Auf dem Wasser eines Salzsees.'::text),
(312307,34701,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... вони відпочивають? На воді солоного озера.'::text,'Де'::text,'Коли'::text,'Хто'::text,'Де вони відпочивають? На воді солоного озера.'::text),
(312306,34701,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... se relajan ellos? En el agua de un lago salado.'::text,'Dónde'::text,'Cuándo'::text,'Quién'::text,'¿Dónde se relajan ellos? En el agua de un lago salado.'::text),
(312305,34701,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... se détendent-ils ? Sur l''eau d''un lac salé.'::text,'Où'::text,'Quand'::text,'Qui'::text,'Où se détendent-ils ? Sur l''eau d''un lac salé.'::text),
(312308,34701,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onlar ... dinleniyor? Bir tuz gölünün suyunda.'::text,'nerede'::text,'ne zaman'::text,'kim'::text,'Onlar nerede dinleniyor? Bir tuz gölünün suyunda.'::text),
(312309,34701,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... pihennek ők? Egy sós tó vizén.'::text,'Hol'::text,'Mikor'::text,'Ki'::text,'Hol pihennek ők? Egy sós tó vizén.'::text),
(312366,34708,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, er hat mir die Seeregel gesagt: Du ... ohne Handy entspannen.'::text,'musst'::text,'musst'::text,'solltest'::text,'Mädel, er hat mir die Seeregel gesagt: Du musst ohne Handy entspannen.'::text),
(312370,34708,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, він сказав мені правило озера: ти ... відпочивати без телефону.'::text,'маєш'::text,'мусиш'::text,'мав би'::text,'Подруго, він сказав мені правило озера: ти маєш відпочивати без телефону.'::text),
(312369,34708,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, él me dijo la regla del lago: tú ... relajarte sin móvil.'::text,'tienes que'::text,'debes'::text,'deberías'::text,'Tía, él me dijo la regla del lago: tú tienes que relajarte sin móvil.'::text),
(312368,34708,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, il m''a dit la règle du lac : tu ... te détendre sans téléphone.'::text,'dois'::text,'dois'::text,'devrais'::text,'Meuf, il m''a dit la règle du lac : tu dois te détendre sans téléphone.'::text),
(312371,34708,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, o bana gölün kuralını söyledi: sen telefonsuz ...'::text,'dinlenmek zorundasın'::text,'dinlenmelisin'::text,'dinlenmelisin'::text,'Kızım, o bana gölün kuralını söyledi: sen telefonsuz dinlenmek zorundasın.'::text),
(312372,34708,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, ő elmondta nekem a tó szabályát: neked telefon nélkül ... pihenned.'::text,'kell'::text,'kell'::text,'kellene'::text,'Csajszi, ő elmondta nekem a tó szabályát: neked telefon nélkül kell pihenned.'::text),
(309351,34373,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Jet ist so nah! Ein Fotograf reißt panisch ... Objektiv hoch!'::text,'sein'::text,'ihr'::text,'ihr'::text,'Der Jet ist so nah! Ein Fotograf reißt panisch sein Objektiv hoch!'::text),
(309355,34373,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Літак так близько! Фотограф у паніці задирає ... об''єктив!'::text,'свій'::text,'свій'::text,'свій'::text,'Літак так близько! Фотограф у паніці задирає свій об''єктив!'::text),
(309354,34373,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El avión está tan cerca! ¡Un fotógrafo levanta ... objetivo presa del pánico!'::text,'su'::text,'su'::text,'su'::text,'¡El avión está tan cerca! ¡Un fotógrafo levanta su objetivo presa del pánico!'::text),
(309353,34373,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''avion est si proche ! Un photographe relève ... objectif en panique !'::text,'son'::text,'son'::text,'leur'::text,'L''avion est si proche ! Un photographe relève son objectif en panique !'::text),
(309356,34373,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jet çok yakın! Bir fotoğrafçı panikle ... objektifini yukarı çeviriyor!'::text,'onun'::text,'onun'::text,'onların'::text,'Jet çok yakın! Bir fotoğrafçı panikle onun objektifini yukarı çeviriyor!'::text),
(309357,34373,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gép olyan közel van! Egy fotós pánikban felrántja az ...!'::text,'objektívjét'::text,'objektívjét'::text,'objektívjüket'::text,'A gép olyan közel van! Egy fotós pánikban felrántja az objektívjét!'::text),
(309405,34379,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Flughafenregeln sagen, dass Fotografen hinter dem Zaun bleiben ...'::text,'müssen'::text,'müssen'::text,'sollten'::text,'Die Flughafenregeln sagen, dass Fotografen hinter dem Zaun bleiben müssen.'::text),
(309409,34379,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Правила аеропорту кажуть, що фотографи ... залишатися за парканом.'::text,'мають'::text,'мусять'::text,'мали б'::text,'Правила аеропорту кажуть, що фотографи мають залишатися за парканом.'::text),
(309408,34379,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las normas del aeropuerto dicen que los fotógrafos ... quedarse detrás de la valla.'::text,'tienen que'::text,'deben'::text,'deberían'::text,'Las normas del aeropuerto dicen que los fotógrafos tienen que quedarse detrás de la valla.'::text),
(309407,34379,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le règlement de l''aéroport dit que les photographes ... rester derrière la clôture.'::text,'doivent'::text,'doivent'::text,'devraient'::text,'Le règlement de l''aéroport dit que les photographes doivent rester derrière la clôture.'::text),
(309410,34379,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Havalimanı kurallarına göre fotoğrafçılar çitin arkasında ...'::text,'kalmak zorunda'::text,'kalmalı'::text,'kalmalı'::text,'Havalimanı kurallarına göre fotoğrafçılar çitin arkasında kalmak zorunda.'::text),
(309411,34379,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A reptéri szabályok szerint a fotósoknak a kerítés mögött ... maradniuk.'::text,'kell'::text,'kell'::text,'kellene'::text,'A reptéri szabályok szerint a fotósoknak a kerítés mögött kell maradniuk.'::text),
(314562,34952,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... Möwen fliegen ganz nah an den Mann heran.'::text,'Diese'::text,'Diese'::text,'Jene'::text,'Diese Möwen fliegen ganz nah an den Mann heran.'::text),
(314566,34952,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... чайки літають дуже близько до чоловіка.'::text,'Ці'::text,'Ця'::text,'Та'::text,'Ці чайки літають дуже близько до чоловіка.'::text),
(314565,34952,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... gaviotas vuelan muy cerca del hombre.'::text,'Estas'::text,'Esta'::text,'Esa'::text,'Estas gaviotas vuelan muy cerca del hombre.'::text),
(314564,34952,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... mouettes volent très près de l''homme.'::text,'Ces'::text,'Cette'::text,'Cette'::text,'Ces mouettes volent très près de l''homme.'::text),
(314567,34952,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... martılar adama çok yakın uçuyor.'::text,'Bu'::text,'Bu'::text,'Şu'::text,'Bu martılar adama çok yakın uçuyor.'::text),
(314568,34952,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a sirályok nagyon közel repülnek a férfihoz.'::text,'Ezek'::text,'Ez'::text,'Az'::text,'Ezek a sirályok nagyon közel repülnek a férfihoz.'::text),
(314598,34956,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er gibt den Möwen etwas ... aus der Hand.'::text,'Brot'::text,'Brot'::text,'ein Brot'::text,'Er gibt den Möwen etwas Brot aus der Hand.'::text),
(314602,34956,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він дає чайкам трохи ... з руки.'::text,'хліба'::text,'хліба'::text,'хліба'::text,'Він дає чайкам трохи хліба з руки.'::text),
(314601,34956,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él les da a las gaviotas algo de ... de su mano.'::text,'pan'::text,'pan'::text,'un pan'::text,'Él les da a las gaviotas algo de pan de su mano.'::text),
(314600,34956,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il donne un peu de ... aux mouettes dans sa main.'::text,'pain'::text,'pain'::text,'un pain'::text,'Il donne un peu de pain aux mouettes dans sa main.'::text),
(314603,34956,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O martılara elinden biraz ... veriyor.'::text,'ekmek'::text,'ekmekler'::text,'bir ekmek'::text,'O martılara elinden biraz ekmek veriyor.'::text),
(314604,34956,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő ad egy kis ... a sirályoknak a kezéből.'::text,'kenyeret'::text,'kenyeret'::text,'egy kenyeret'::text,'Ő ad egy kis kenyeret a sirályoknak a kezéből.'::text),
(297975,33109,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Führerin ... die Gruppe eine schmale Gasse hinunter.'::text,'führt'::text,'führen'::text,'führend'::text,'Die Führerin führt die Gruppe eine schmale Gasse hinunter.'::text),
(297979,33109,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Екскурсоводка ... групу вузьким провулком.'::text,'веде'::text,'вести'::text,'ведучи'::text,'Екскурсоводка веде групу вузьким провулком.'::text),
(297978,33109,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La guía ... al grupo por un callejón estrecho.'::text,'lleva'::text,'llevar'::text,'llevando'::text,'La guía lleva al grupo por un callejón estrecho.'::text),
(297977,33109,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La guide ... le groupe dans une ruelle étroite.'::text,'mène'::text,'mener'::text,'menant'::text,'La guide mène le groupe dans une ruelle étroite.'::text),
(297980,33109,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rehber grubu dar bir sokaktan ...'::text,'götürür'::text,'götürmek'::text,'götürerek'::text,'Rehber grubu dar bir sokaktan götürür.'::text),
(297981,33109,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az idegenvezető ... a csoportot egy szűk sikátoron.'::text,'vezeti'::text,'vezetni'::text,'vezető'::text,'Az idegenvezető vezeti a csoportot egy szűk sikátoron.'::text),
(298029,33115,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eine ruhige Straße, klar. Die Führerin hebt den Schirm, ... verläuft sich niemand.'::text,'also'::text,'aber'::text,'weil'::text,'Eine ruhige Straße, klar. Die Führerin hebt den Schirm, also verläuft sich niemand.'::text),
(298033,33115,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Тиха вулиця, звісно. Екскурсоводка піднімає парасольку, ... ніхто не загубиться.'::text,'тому'::text,'але'::text,'бо'::text,'Тиха вулиця, звісно. Екскурсоводка піднімає парасольку, тому ніхто не загубиться.'::text),
(298032,33115,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Una calle tranquila, obviamente. La guía levanta el paraguas, ... nadie se pierde.'::text,'así que'::text,'pero'::text,'porque'::text,'Una calle tranquila, obviamente. La guía levanta el paraguas, así que nadie se pierde.'::text),
(298031,33115,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une rue calme, évidemment. La guide lève le parapluie, ... personne ne se perd.'::text,'donc'::text,'mais'::text,'parce que'::text,'Une rue calme, évidemment. La guide lève le parapluie, donc personne ne se perd.'::text),
(298034,33115,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sessiz bir sokak, belli ki. Rehber şemsiyeyi kaldırıyor, ... kimse kaybolmuyor.'::text,'bu yüzden'::text,'ama'::text,'çünkü'::text,'Sessiz bir sokak, belli ki. Rehber şemsiyeyi kaldırıyor, bu yüzden kimse kaybolmuyor.'::text),
(298035,33115,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csendes utca, nyilván. Az idegenvezető felemeli az esernyőt, ... senki sem téved el.'::text,'ezért'::text,'de'::text,'mert'::text,'Csendes utca, nyilván. Az idegenvezető felemeli az esernyőt, ezért senki sem téved el.'::text),
(295275,32809,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ist Frankreich? In Frankreich, weil Frankreich eben dort ist.'::text,'Wo'::text,'Was'::text,'Wer'::text,'Wo ist Frankreich? In Frankreich, weil Frankreich eben dort ist.'::text),
(295279,32809,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... Франція? У Франції, бо саме там Франція і є.'::text,'Де'::text,'Що'::text,'Хто'::text,'Де Франція? У Франції, бо саме там Франція і є.'::text),
(295278,32809,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... está Francia? En Francia, porque ahí es donde está Francia.'::text,'Dónde'::text,'Qué'::text,'Quién'::text,'¿Dónde está Francia? En Francia, porque ahí es donde está Francia.'::text),
(295277,32809,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... est la France ? En France, parce que c''est là que se trouve la France.'::text,'Où'::text,'Que'::text,'Qui'::text,'Où est la France ? En France, parce que c''est là que se trouve la France.'::text),
(295280,32809,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fransa ...? Fransa''da, çünkü Fransa orada.'::text,'nerede'::text,'ne'::text,'kim'::text,'Fransa nerede? Fransa''da, çünkü Fransa orada.'::text),
(295281,32809,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... van Franciaország? Franciaországban, mert ott van Franciaország.'::text,'Hol'::text,'Mi'::text,'Ki'::text,'Hol van Franciaország? Franciaországban, mert ott van Franciaország.'::text),
(295329,32815,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee Digga, sie arbeitet sonst, aber heute in Frankreich ... sie Croissants.'::text,'isst'::text,'isst'::text,NULL::text,'Nee Digga, sie arbeitet sonst, aber heute in Frankreich isst sie Croissants.'::text),
(295333,32815,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, бро, вона зазвичай працює, але сьогодні у Франції ... круасани.'::text,'їсть'::text,'їсть'::text,NULL::text,'Не, бро, вона зазвичай працює, але сьогодні у Франції їсть круасани.'::text),
(295332,32815,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, tío, ella normalmente trabaja, pero hoy en Francia ... cruasanes.'::text,'está comiendo'::text,'come'::text,NULL::text,'Qué va, tío, ella normalmente trabaja, pero hoy en Francia está comiendo cruasanes.'::text),
(295331,32815,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Non frérot, d''habitude elle bosse, mais aujourd''hui en France elle ... des croissants.'::text,'est en train de manger'::text,'mange'::text,NULL::text,'Non frérot, d''habitude elle bosse, mais aujourd''hui en France elle est en train de manger des croissants.'::text),
(295334,32815,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok kanka, o genelde çalışır ama bugün Fransa''da kruvasan ...'::text,'yiyor'::text,'yer'::text,NULL::text,'Yok kanka, o genelde çalışır ama bugün Fransa''da kruvasan yiyor.'::text),
(295335,32815,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem, tesó, ő általában dolgozik, de ma Franciaországban croissant-t ...'::text,'eszik'::text,'eszik'::text,NULL::text,'Nem, tesó, ő általában dolgozik, de ma Franciaországban croissant-t eszik.'::text),
(295446,32828,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er hat jetzt Freiheit, also glaube ich, dass er frei ...'::text,'sein wird'::text,'sein wird'::text,NULL::text,'Er hat jetzt Freiheit, also glaube ich, dass er frei sein wird.'::text),
(295450,32828,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Тепер у нього є свобода, тож я думаю, що він ... вільним.'::text,'буде'::text,'буде'::text,NULL::text,'Тепер у нього є свобода, тож я думаю, що він буде вільним.'::text),
(295449,32828,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora él tiene libertad, así que creo que ... libre.'::text,'será'::text,'va a ser'::text,NULL::text,'Ahora él tiene libertad, así que creo que será libre.'::text),
(295448,32828,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a la liberté maintenant, donc je pense qu''il ... libre.'::text,'sera'::text,'va être'::text,NULL::text,'Il a la liberté maintenant, donc je pense qu''il sera libre.'::text),
(295451,32828,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Artık özgürlüğü var, bu yüzden bence o özgür ...'::text,'olacak'::text,'olacak'::text,NULL::text,'Artık özgürlüğü var, bu yüzden bence o özgür olacak.'::text),
(295452,32828,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Most már szabadsága van, ezért azt hiszem, ő szabad ...'::text,'lesz'::text,'lesz'::text,NULL::text,'Most már szabadsága van, ezért azt hiszem, ő szabad lesz.'::text),
(296004,32890,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... den Kühlschrank, bis jedes Fach voll ist.'::text,'füllt'::text,'füllen'::text,'füllend'::text,'Er füllt den Kühlschrank, bis jedes Fach voll ist.'::text),
(296008,32890,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... холодильник, доки кожна полиця не стане повною.'::text,'заповнює'::text,'заповнювати'::text,'заповнюючи'::text,'Він заповнює холодильник, доки кожна полиця не стане повною.'::text),
(296007,32890,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... la nevera hasta que cada estante esté lleno.'::text,'llena'::text,'llenar'::text,'llenando'::text,'Él llena la nevera hasta que cada estante esté lleno.'::text),
(296006,32890,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... le frigo jusqu''à ce que chaque étagère soit pleine.'::text,'remplit'::text,'remplir'::text,'remplissant'::text,'Il remplit le frigo jusqu''à ce que chaque étagère soit pleine.'::text),
(296009,32890,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O her raf dolana kadar buzdolabını ...'::text,'doldurur'::text,'doldurmak'::text,'doldurarak'::text,'O her raf dolana kadar buzdolabını doldurur.'::text),
(296010,32890,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő addig ... a hűtőt, amíg minden polc tele nem lesz.'::text,'tölti'::text,'tölteni'::text,'töltő'::text,'Ő addig tölti a hűtőt, amíg minden polc tele nem lesz.'::text),
(296049,32895,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du hast den vollen Kühlschrank so ... eingeräumt. Beeindruckend.'::text,'ordentlich'::text,'ordentlich'::text,'Ordnung'::text,'Ehrlich, du hast den vollen Kühlschrank so ordentlich eingeräumt. Beeindruckend.'::text),
(296053,32895,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти заповнив цей повний холодильник так ... Вражає.'::text,'акуратно'::text,'акуратний'::text,'акуратність'::text,'Чесно, ти заповнив цей повний холодильник так акуратно Вражає.'::text),
(296052,32895,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En serio, tú llenaste esa nevera tan ... Impresionante.'::text,'ordenadamente'::text,'ordenado'::text,'orden'::text,'En serio, tú llenaste esa nevera tan ordenadamente Impresionante.'::text),
(296051,32895,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu as rempli ce frigo plein si ... Impressionnant.'::text,'soigneusement'::text,'soigné'::text,'soin'::text,'Franchement, tu as rempli ce frigo plein si soigneusement Impressionnant.'::text),
(296054,32895,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası sen o dolu buzdolabını çok ... yerleştirdin. Etkileyici.'::text,'düzgünce'::text,'düzgün'::text,'düzgünlük'::text,'Açıkçası sen o dolu buzdolabını çok düzgünce yerleştirdin. Etkileyici.'::text),
(296055,32895,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, te olyan ... pakoltad be azt a teli hűtőt. Lenyűgöző.'::text,'rendesen'::text,'rendes'::text,'rendesség'::text,'Őszintén, te olyan rendesen pakoltad be azt a teli hűtőt. Lenyűgöző.'::text),
(315354,35040,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... sein Eis mit seinem Freund.'::text,'teilt'::text,'teilen'::text,'teilend'::text,'Er teilt sein Eis mit seinem Freund.'::text),
(315358,35040,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... своїм морозивом із другом.'::text,'ділиться'::text,'ділитися'::text,'ділячись'::text,'Він ділиться своїм морозивом із другом.'::text),
(315357,35040,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... su helado con su amigo.'::text,'comparte'::text,'compartir'::text,'compartiendo'::text,'Él comparte su helado con su amigo.'::text),
(315356,35040,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... sa glace avec son ami.'::text,'partage'::text,'partager'::text,'partageant'::text,'Il partage sa glace avec son ami.'::text),
(315359,35040,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O dondurmasını arkadaşıyla ...'::text,'paylaşır'::text,'paylaşmak'::text,'paylaşarak'::text,'O dondurmasını arkadaşıyla paylaşır.'::text),
(315360,35040,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő ... a fagyiját a barátjával.'::text,'megosztja'::text,'megosztani'::text,'megosztó'::text,'Ő megosztja a fagyiját a barátjával.'::text),
(315408,35046,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Es ist das letzte Eis der Welt! Du ... es teilen!'::text,'solltest'::text,'sollst'::text,'solltest'::text,'Es ist das letzte Eis der Welt! Du solltest es teilen!'::text),
(315412,35046,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Це останнє морозиво у світі! Ти ... ним поділитися!'::text,'мав би'::text,'будеш'::text,'мав би'::text,'Це останнє морозиво у світі! Ти мав би ним поділитися!'::text),
(315411,35046,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Es el último helado del mundo! ¡Tú ... compartirlo!'::text,'deberías'::text,'deberás'::text,'deberías'::text,'¡Es el último helado del mundo! ¡Tú deberías compartirlo!'::text),
(315410,35046,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'C''est la dernière glace au monde ! Tu ... la partager !'::text,'devrais'::text,'devras'::text,'devrais'::text,'C''est la dernière glace au monde ! Tu devrais la partager !'::text),
(315413,35046,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu dünyadaki son dondurma! Sen onu ...!'::text,'paylaşmalısın'::text,'paylaşacaksın'::text,'paylaşmalısın'::text,'Bu dünyadaki son dondurma! Sen onu paylaşmalısın!'::text),
(315414,35046,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez az utolsó fagyi a világon! Neked meg ... osztanod!'::text,'kellene'::text,'kell'::text,'kellene'::text,'Ez az utolsó fagyi a világon! Neked meg kellene osztanod!'::text),
(317991,35333,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihr Sofa ist ... altes grünes Sofa.'::text,'ein'::text,'ein'::text,'das'::text,'Ihr Sofa ist ein altes grünes Sofa.'::text),
(317995,35333,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Їхній диван — ... старий зелений диван.'::text,''::text,NULL::text,NULL::text,'Їхній диван — старий зелений диван.'::text),
(317994,35333,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su sofá es ... sofá verde viejo.'::text,'un'::text,'un'::text,'el'::text,'Su sofá es un sofá verde viejo.'::text),
(317993,35333,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Leur canapé est ... vieux canapé vert.'::text,'un'::text,'un'::text,'le'::text,'Leur canapé est un vieux canapé vert.'::text),
(317996,35333,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onların kanepesi ... eski yeşil kanepe.'::text,'bir'::text,'bir'::text,NULL::text,'Onların kanepesi bir eski yeşil kanepe.'::text),
(317997,35333,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az ő kanapéjuk ... régi zöld kanapé.'::text,'egy'::text,'egy'::text,'a'::text,'Az ő kanapéjuk egy régi zöld kanapé.'::text),
(318036,35338,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, sie hat mir erzählt, dass jetzt überall auf dem Sofa Chips ...'::text,'sind'::text,'ist'::text,'sein'::text,'Mädel, sie hat mir erzählt, dass jetzt überall auf dem Sofa Chips sind.'::text),
(318040,35338,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, вона мені сказала, що тепер по всьому дивану ... чипси.'::text,'є'::text,'є'::text,'бути'::text,'Подруго, вона мені сказала, що тепер по всьому дивану є чипси.'::text),
(318039,35338,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, ella me dijo que ahora ... patatas fritas por todo el sofá.'::text,'hay'::text,'hay'::text,'hay'::text,'Tía, ella me dijo que ahora hay patatas fritas por todo el sofá.'::text),
(318038,35338,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, elle m''a dit que maintenant, ... des chips partout sur le canapé.'::text,'il y a'::text,'il y a'::text,'il y a'::text,'Meuf, elle m''a dit que maintenant, il y a des chips partout sur le canapé.'::text),
(318041,35338,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, o bana şimdi kanepenin her yerinde cips ... dedi.'::text,'var'::text,'var'::text,'olmak'::text,'Kızım, o bana şimdi kanepenin her yerinde cips var dedi.'::text),
(318042,35338,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, ő azt mondta nekem, hogy most mindenhol chips ... a kanapén.'::text,'van'::text,'vannak'::text,'lenni'::text,'Csajszi, ő azt mondta nekem, hogy most mindenhol chips van a kanapén.'::text),
(296445,32939,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Tomaten sind reif, also ... sie morgen wieder im Garten arbeiten.'::text,'wird'::text,'arbeitet'::text,'arbeitete'::text,'Die Tomaten sind reif, also wird sie morgen wieder im Garten arbeiten.'::text),
(296449,32939,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Помідори стиглі, тож вона завтра знову ... в саду.'::text,'працюватиме'::text,'працює'::text,'працювала'::text,'Помідори стиглі, тож вона завтра знову працюватиме в саду.'::text),
(296448,32939,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los tomates están maduros, así que ella ... en el huerto otra vez mañana.'::text,'trabajará'::text,'trabaja'::text,'trabajó'::text,'Los tomates están maduros, así que ella trabajará en el huerto otra vez mañana.'::text),
(296447,32939,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les tomates sont mûres, donc elle ... encore demain.'::text,'jardinera'::text,'jardine'::text,'a jardiné'::text,'Les tomates sont mûres, donc elle jardinera encore demain.'::text),
(296450,32939,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Domatesler olgun, bu yüzden o yarın yine bahçede ...'::text,'çalışacak'::text,'çalışır'::text,'çalıştı'::text,'Domatesler olgun, bu yüzden o yarın yine bahçede çalışacak.'::text),
(296451,32939,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A paradicsomok érettek, ezért ő holnap újra ... a kertben.'::text,'dolgozni fog'::text,'dolgozik'::text,'dolgozott'::text,'A paradicsomok érettek, ezért ő holnap újra dolgozni fog a kertben.'::text),
(296535,32949,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Gärtnerin hat Werkzeug in ... Schürzentaschen.'::text,'ihren'::text,'seinen'::text,'seinen'::text,'Die Gärtnerin hat Werkzeug in ihren Schürzentaschen.'::text),
(296539,32949,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Садівниця має інструменти в кишенях ... фартуха.'::text,'свого'::text,'свого'::text,'свого'::text,'Садівниця має інструменти в кишенях свого фартуха.'::text),
(296538,32949,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La jardinera tiene herramientas en ... bolsillos del delantal.'::text,'sus'::text,'sus'::text,'sus'::text,'La jardinera tiene herramientas en sus bolsillos del delantal.'::text),
(296537,32949,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La jardinière a des outils dans ... poches de tablier.'::text,'ses'::text,'ses'::text,'ses'::text,'La jardinière a des outils dans ses poches de tablier.'::text),
(296540,32949,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bahçıvanın ... önlük ceplerinde aletler var.'::text,'onun'::text,'onun'::text,'onun'::text,'Bahçıvanın onun önlük ceplerinde aletler var.'::text),
(296541,32949,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kertésznő szerszámokat tart a kötényének ...'::text,'zsebeiben'::text,'zsebeiben'::text,'zsebeiben'::text,'A kertésznő szerszámokat tart a kötényének zsebeiben.'::text),
(296562,32952,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, die Gärtnerin gießt so viel ... auf die Blumen, lowkey.'::text,'Wasser'::text,'Wasser'::text,'ein Wasser'::text,'Alter, die Gärtnerin gießt so viel Wasser auf die Blumen, lowkey.'::text),
(296566,32952,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, садівниця ллє на квіти стільки ..., лоукі.'::text,'води'::text,'води'::text,'води'::text,'Чувак, садівниця ллє на квіти стільки води, лоукі.'::text),
(296565,32952,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, la jardinera echa tanta ... en las flores, la verdad.'::text,'agua'::text,'agua'::text,'un agua'::text,'Tío, la jardinera echa tanta agua en las flores, la verdad.'::text),
(296564,32952,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, la jardinière verse tellement ... sur les fleurs, discret.'::text,'d''eau'::text,'d''eau'::text,'d''une eau'::text,'Mec, la jardinière verse tellement d''eau sur les fleurs, discret.'::text),
(296567,32952,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bahçıvan çiçeklere o kadar çok ... döküyor ki, lowkey.'::text,'su'::text,'sular'::text,'bir su'::text,'Kanka, bahçıvan çiçeklere o kadar çok su döküyor ki, lowkey.'::text),
(296568,32952,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Haver, a kertész annyi ... önt a virágokra, lowkey.'::text,'vizet'::text,'vizet'::text,'egy vizet'::text,'Haver, a kertész annyi vizet önt a virágokra, lowkey.'::text),
(294258,32696,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Budget für den Aussichtspunkt: ein neuer Zaun. ... Zaun kostet 900 Euro.'::text,'Der'::text,'Ein'::text,'Ein'::text,'Budget für den Aussichtspunkt: ein neuer Zaun. Der Zaun kostet 900 Euro.'::text),
(294262,32696,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бюджет оглядового майданчика: новий паркан. ... Паркан коштує 900 євро.'::text,''::text,NULL::text,NULL::text,'Бюджет оглядового майданчика: новий паркан. Паркан коштує 900 євро.'::text),
(294261,32696,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Presupuesto del mirador: una valla nueva. ... valla cuesta 900 euros.'::text,'La'::text,'Una'::text,'Una'::text,'Presupuesto del mirador: una valla nueva. La valla cuesta 900 euros.'::text),
(294260,32696,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Budget du belvédère : une nouvelle clôture. ... clôture coûte 900 euros.'::text,'La'::text,'Une'::text,'Une'::text,'Budget du belvédère : une nouvelle clôture. La clôture coûte 900 euros.'::text),
(294263,32696,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Seyir noktası bütçesi: yeni bir çit. ... Çit 900 euro tutuyor.'::text,''::text,'Bir'::text,'Bir'::text,'Seyir noktası bütçesi: yeni bir çit. Çit 900 euro tutuyor.'::text),
(294264,32696,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kilátópont-költségvetés: egy új kerítés. ... kerítés 900 euróba kerül.'::text,'A'::text,'Egy'::text,'Egy'::text,'Kilátópont-költségvetés: egy új kerítés. A kerítés 900 euróba kerül.'::text),
(294276,32698,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zwischen dir und dem Abgrund ... ein Zaun, kluge Wahl, ehrlich.'::text,'ist'::text,'sind'::text,'sein'::text,'Zwischen dir und dem Abgrund ist ein Zaun, kluge Wahl, ehrlich.'::text),
(294280,32698,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Між тобою і прірвою ... паркан, розумний вибір, чесно.'::text,'є'::text,'є'::text,'бути'::text,'Між тобою і прірвою є паркан, розумний вибір, чесно.'::text),
(294279,32698,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... una valla entre tú y el precipicio, buena elección, en serio.'::text,'Hay'::text,'Hay'::text,'Hay'::text,'Hay una valla entre tú y el precipicio, buena elección, en serio.'::text),
(294278,32698,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... une clôture entre toi et le vide, choix malin, franchement.'::text,'Il y a'::text,'Il y a'::text,'Il y a'::text,'Il y a une clôture entre toi et le vide, choix malin, franchement.'::text),
(294281,32698,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Seninle uçurum arasında bir çit ..., akıllıca seçim, cidden.'::text,'var'::text,'var'::text,'olmak'::text,'Seninle uçurum arasında bir çit var, akıllıca seçim, cidden.'::text),
(294282,32698,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Közted és a szakadék között ... egy kerítés, okos választás, őszintén.'::text,'van'::text,'vannak'::text,'lenni'::text,'Közted és a szakadék között van egy kerítés, okos választás, őszintén.'::text),
(308046,34228,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du öffnest ... Tore, um diesen Palast zu finden? Respekt.'::text,'vier'::text,'vierte'::text,'für'::text,'Du öffnest vier Tore, um diesen Palast zu finden? Respekt.'::text),
(308050,34228,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти відчиняєш ... брами, щоб знайти той палац? Респект.'::text,'чотири'::text,'четверту'::text,'для'::text,'Ти відчиняєш чотири брами, щоб знайти той палац? Респект.'::text),
(308049,34228,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿Tú abres ... puertas para encontrar ese palacio? Respeto.'::text,'cuatro'::text,'cuartas'::text,'para'::text,'¿Tú abres cuatro puertas para encontrar ese palacio? Respeto.'::text),
(308048,34228,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ouvres ... portes pour trouver ce palais ? Respect.'::text,'quatre'::text,'quatrièmes'::text,'pour'::text,'Tu ouvres quatre portes pour trouver ce palais ? Respect.'::text),
(308051,34228,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sen o sarayı bulmak için ... kapı mı açıyorsun? Saygı.'::text,'dört'::text,'dördüncü'::text,'için'::text,'Sen o sarayı bulmak için dört kapı mı açıyorsun? Saygı.'::text),
(308052,34228,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te ... kaput nyitsz ki, hogy megtaláld azt a palotát? Respekt.'::text,'négy'::text,'negyedik'::text,'számára'::text,'Te négy kaput nyitsz ki, hogy megtaláld azt a palotát? Respekt.'::text),
(308055,34229,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gestern ... sie vier Tore und fand einen Palast.'::text,'öffnete'::text,'öffnet'::text,'öffnen'::text,'Gestern öffnete sie vier Tore und fand einen Palast.'::text),
(308059,34229,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Учора вона ... чотири брами і знайшла палац.'::text,'відчинила'::text,'відчиняє'::text,'відчиняти'::text,'Учора вона відчинила чотири брами і знайшла палац.'::text),
(308058,34229,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ayer ella ... cuatro puertas y encontró un palacio.'::text,'abrió'::text,'abre'::text,'abrir'::text,'Ayer ella abrió cuatro puertas y encontró un palacio.'::text),
(308057,34229,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hier, elle ... quatre portes et a trouvé un palais.'::text,'a ouvert'::text,'ouvre'::text,'ouvrir'::text,'Hier, elle a ouvert quatre portes et a trouvé un palais.'::text),
(308060,34229,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dün o dört kapı ... ve bir saray buldu.'::text,'açtı'::text,'açar'::text,'açmak'::text,'Dün o dört kapı açtı ve bir saray buldu.'::text),
(308061,34229,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tegnap ő négy kaput ... ki, és talált egy palotát.'::text,'nyitott'::text,'nyit'::text,'nyitni'::text,'Tegnap ő négy kaput nyitott ki, és talált egy palotát.'::text),
(296661,32963,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wie ... Generationen der Familie sind im Garten?'::text,'viele'::text,'viel'::text,'einige'::text,'Wie viele Generationen der Familie sind im Garten?'::text),
(296665,32963,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... поколінь родини в саду?'::text,'Скільки'::text,'Скільки'::text,'Кілька'::text,'Скільки поколінь родини в саду?'::text),
(296664,32963,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... generaciones de la familia hay en el jardín?'::text,'Cuántas'::text,'Cuánta'::text,'Algunas'::text,'¿Cuántas generaciones de la familia hay en el jardín?'::text),
(296663,32963,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... générations de la famille y a-t-il dans le jardin ?'::text,'Combien de'::text,'Combien de'::text,'Des'::text,'Combien de générations de la famille y a-t-il dans le jardin ?'::text),
(296666,32963,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bahçede ailenin ... kuşağı var?'::text,'kaç'::text,'kaç'::text,'bazı'::text,'Bahçede ailenin kaç kuşağı var?'::text),
(296667,32963,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... generációja van a családnak a kertben?'::text,'Hány'::text,'Mennyi'::text,'Néhány'::text,'Hány generációja van a családnak a kertben?'::text),
(310269,34475,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er lüftet seinen Zylinder. Er ist ... als die anderen Männer im Park.'::text,'höflicher'::text,'am höflichsten'::text,'höflicher'::text,'Er lüftet seinen Zylinder. Er ist höflicher als die anderen Männer im Park.'::text),
(310273,34475,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він піднімає циліндр. Він ... за інших чоловіків у парку.'::text,'більш ввічливий'::text,'найввічливіший'::text,'ввічливіший'::text,'Він піднімає циліндр. Він більш ввічливий за інших чоловіків у парку.'::text),
(310272,34475,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se quita la chistera. Él es ... que los otros hombres del parque.'::text,'más educado'::text,'el más educado'::text,'más educado'::text,'Se quita la chistera. Él es más educado que los otros hombres del parque.'::text),
(310271,34475,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il soulève son haut-de-forme. Il est ... que les autres hommes du parc.'::text,'plus poli'::text,'le plus poli'::text,'plus poli'::text,'Il soulève son haut-de-forme. Il est plus poli que les autres hommes du parc.'::text),
(310274,34475,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Silindir şapkasını kaldırıyor. O parktaki diğer adamlardan ...'::text,'daha kibar'::text,'en kibar'::text,'daha kibar'::text,'Silindir şapkasını kaldırıyor. O parktaki diğer adamlardan daha kibar.'::text),
(310275,34475,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Megemeli a cilinderét. Ő ..., mint a többi férfi a parkban.'::text,'udvariasabb'::text,'legudvariasabb'::text,'udvariasabb'::text,'Megemeli a cilinderét. Ő udvariasabb, mint a többi férfi a parkban.'::text),
(299640,33294,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann im grauen Anzug ... sehr hilfsbereit zu den Leuten.'::text,'ist'::text,'sind'::text,'bin'::text,'Der Mann im grauen Anzug ist sehr hilfsbereit zu den Leuten.'::text),
(299644,33294,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік у сірому костюмі ... дуже чуйний до людей.'::text,'є'::text,'є'::text,'є'::text,'Чоловік у сірому костюмі є дуже чуйний до людей.'::text),
(299643,33294,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre del traje gris ... muy servicial con la gente.'::text,'es'::text,'son'::text,'soy'::text,'El hombre del traje gris es muy servicial con la gente.'::text),
(299642,33294,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme au costume gris ... très serviable avec les gens.'::text,'est'::text,'sont'::text,'suis'::text,'L''homme au costume gris est très serviable avec les gens.'::text),
(299645,33294,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gri takım elbiseli adam insanlara karşı çok yardımsever ...'::text,''::text,NULL::text,NULL::text,'Gri takım elbiseli adam insanlara karşı çok yardımsever.'::text),
(299646,33294,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szürke öltönyös férfi ... nagyon segítőkész az emberekkel.'::text,''::text,NULL::text,'vagyok'::text,'A szürke öltönyös férfi nagyon segítőkész az emberekkel.'::text),
(299676,33298,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich gesagt, mit dem offenen Schirm ... du sie trocken halten. So hilfsbereit.'::text,'wirst'::text,'wirst'::text,NULL::text,'Ehrlich gesagt, mit dem offenen Schirm wirst du sie trocken halten. So hilfsbereit.'::text),
(299680,33298,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, з цією відкритою парасолькою ти ... вберегти її від дощу. Такий турботливий.'::text,'збираєшся'::text,'будеш'::text,NULL::text,'Чесно, з цією відкритою парасолькою ти збираєшся вберегти її від дощу. Такий турботливий.'::text),
(299679,33298,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No te voy a mentir, con ese paraguas abierto tú ... mantenerla seca. Qué atento.'::text,'vas a'::text,NULL::text,NULL::text,'No te voy a mentir, con ese paraguas abierto tú vas a mantenerla seca. Qué atento.'::text),
(299678,33298,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sans mentir, avec ce parapluie ouvert, tu ... la garder au sec. Trop serviable.'::text,'vas'::text,NULL::text,NULL::text,'Sans mentir, avec ce parapluie ouvert, tu vas la garder au sec. Trop serviable.'::text),
(299681,33298,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, o açık şemsiyeyle sen onu kuru ... Ne kadar yardımsever.'::text,'tutacaksın'::text,'tutacaksın'::text,NULL::text,'Yalan yok, o açık şemsiyeyle sen onu kuru tutacaksın Ne kadar yardımsever.'::text),
(299682,33298,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hazudok, azzal a nyitott esernyővel te szárazon ... tartani őt. Milyen segítőkész.'::text,'fogod'::text,'fogod'::text,NULL::text,'Nem hazudok, azzal a nyitott esernyővel te szárazon fogod tartani őt. Milyen segítőkész.'::text),
(296688,32966,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... mit nur einem Rucksack durch Deutschland? Respekt.'::text,'reist'::text,'reist'::text,'zu reisen'::text,'Du reist mit nur einem Rucksack durch Deutschland? Respekt.'::text),
(296692,32966,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... Німеччиною лише з одним рюкзаком? Респект.'::text,'подорожуєш'::text,'подорожує'::text,'подорожувати'::text,'Ти подорожуєш Німеччиною лише з одним рюкзаком? Респект.'::text),
(296691,32966,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿Tú ... por Alemania con solo una mochila? Respeto.'::text,'viajas'::text,'viaja'::text,'viajar'::text,'¿Tú viajas por Alemania con solo una mochila? Respeto.'::text),
(296690,32966,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... en Allemagne avec un seul sac à dos ? Respect.'::text,'voyages'::text,'voyage'::text,'voyager'::text,'Tu voyages en Allemagne avec un seul sac à dos ? Respect.'::text),
(296693,32966,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sen Almanya''yı tek bir sırt çantasıyla mı ...? Saygı.'::text,'gezersin'::text,'gezer'::text,'gezmek'::text,'Sen Almanya''yı tek bir sırt çantasıyla mı gezersin? Saygı.'::text),
(296694,32966,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te csak egy hátizsákkal ... Németországban? Respekt.'::text,'utazgatsz'::text,'utazgat'::text,'utazgatni'::text,'Te csak egy hátizsákkal utazgatsz Németországban? Respekt.'::text),
(296715,32969,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, Deutschland hat so viel ..., schau dir die Brezeln an, ohne Witz.'::text,'Brot'::text,'Brot'::text,'ein Brot'::text,'Yo, Deutschland hat so viel Brot, schau dir die Brezeln an, ohne Witz.'::text),
(296719,32969,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, у Німеччині стільки ..., глянь на ті брецелі, без брехні.'::text,'хліба'::text,'хліба'::text,'хліба'::text,'Йо, у Німеччині стільки хліба, глянь на ті брецелі, без брехні.'::text),
(296718,32969,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ey, Alemania tiene tanto ..., mira esos pretzels, en serio.'::text,'pan'::text,'pan'::text,'un pan'::text,'Ey, Alemania tiene tanto pan, mira esos pretzels, en serio.'::text),
(296717,32969,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, l''Allemagne a tellement de ..., regarde ces bretzels, sans mentir.'::text,'pain'::text,'pain'::text,'un pain'::text,'Yo, l''Allemagne a tellement de pain, regarde ces bretzels, sans mentir.'::text),
(296720,32969,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, Almanya''da o kadar çok ... var ki, şu brezellere bak, cidden.'::text,'ekmek'::text,'ekmekler'::text,'bir ekmek'::text,'Kanka, Almanya''da o kadar çok ekmek var ki, şu brezellere bak, cidden.'::text),
(296721,32969,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, Németországban annyi ... van, nézd azokat a pereceket, komolyan.'::text,'kenyér'::text,'kenyér'::text,'egy kenyér'::text,'Figyu, Németországban annyi kenyér van, nézd azokat a pereceket, komolyan.'::text),
(315111,35013,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jetzt ... ihre beiden Leben getrennt.'::text,'sind'::text,'ist'::text,'bin'::text,'Jetzt sind ihre beiden Leben getrennt.'::text),
(315115,35013,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Тепер їхні два життя ... окремі.'::text,'є'::text,'є'::text,'є'::text,'Тепер їхні два життя є окремі.'::text),
(315114,35013,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora sus dos vidas ... separadas.'::text,'están'::text,'está'::text,'estoy'::text,'Ahora sus dos vidas están separadas.'::text),
(315113,35013,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Maintenant, leurs deux vies ... séparées.'::text,'sont'::text,'est'::text,'suis'::text,'Maintenant, leurs deux vies sont séparées.'::text),
(315116,35013,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Artık onların iki hayatı ayrı ...'::text,''::text,NULL::text,NULL::text,'Artık onların iki hayatı ayrı.'::text),
(315117,35013,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Most a két életük ... különálló.'::text,''::text,NULL::text,'vagyok'::text,'Most a két életük különálló.'::text),
(315147,35017,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie legen die Ringe auf den Tisch. Sie ... getrennte Leben führen.'::text,'werden'::text,'werden'::text,NULL::text,'Sie legen die Ringe auf den Tisch. Sie werden getrennte Leben führen.'::text),
(315151,35017,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони кладуть каблучки на стіл. Вони ... жити окремим життям.'::text,'збираються'::text,'будуть'::text,NULL::text,'Вони кладуть каблучки на стіл. Вони збираються жити окремим життям.'::text),
(315150,35017,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ponen los anillos sobre la mesa. Ellos ... vivir vidas separadas.'::text,'van a'::text,NULL::text,NULL::text,'Ponen los anillos sobre la mesa. Ellos van a vivir vidas separadas.'::text),
(315149,35017,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils posent les alliances sur la table. Ils ... vivre des vies séparées.'::text,'vont'::text,NULL::text,NULL::text,'Ils posent les alliances sur la table. Ils vont vivre des vies séparées.'::text),
(315152,35017,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yüzükleri masaya koyuyorlar. Onlar ayrı hayatlar ...'::text,'yaşayacak'::text,'yaşayacak'::text,NULL::text,'Yüzükleri masaya koyuyorlar. Onlar ayrı hayatlar yaşayacak.'::text),
(315153,35017,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Leteszik a gyűrűket az asztalra. Ők külön ... élni.'::text,'fognak'::text,'fognak'::text,NULL::text,'Leteszik a gyűrűket az asztalra. Ők külön fognak élni.'::text),
(304716,33858,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, ... wird sie heiraten? Den Typen im schwarzen Anzug.'::text,'wen'::text,'was'::text,'wo'::text,'Yo, wen wird sie heiraten? Den Typen im schwarzen Anzug.'::text),
(304720,33858,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, за ... вона вийде заміж? За чувака в чорному костюмі.'::text,'кого'::text,'що'::text,'де'::text,'Йо, за кого вона вийде заміж? За чувака в чорному костюмі.'::text),
(304719,33858,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ey, ¿con ... se va a casar ella? Con el tío del traje negro.'::text,'quién'::text,'qué'::text,'dónde'::text,'Ey, ¿con quién se va a casar ella? Con el tío del traje negro.'::text),
(304718,33858,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, ... elle va épouser ? Le mec en costume noir.'::text,'qui'::text,'que'::text,'où'::text,'Yo, qui elle va épouser ? Le mec en costume noir.'::text),
(304721,33858,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o ... ile evlenecek? Siyah takımlı adamla.'::text,'kim'::text,'ne'::text,'nerede'::text,'Kanka, o kim ile evlenecek? Siyah takımlı adamla.'::text),
(304722,33858,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, ... fog ő feleségül menni? A fekete öltönyös csávóhoz.'::text,'kihez'::text,'mihez'::text,'hol'::text,'Figyu, kihez fog ő feleségül menni? A fekete öltönyös csávóhoz.'::text),
(304752,33862,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Leute heiraten oft drinnen, aber dieses Paar ... heute in einem Garten.'::text,'heiratet'::text,'heiratet'::text,NULL::text,'Leute heiraten oft drinnen, aber dieses Paar heiratet heute in einem Garten.'::text),
(304756,33862,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Люди часто одружуються в приміщенні, але ця пара сьогодні ... в саду.'::text,'одружується'::text,'одружується'::text,NULL::text,'Люди часто одружуються в приміщенні, але ця пара сьогодні одружується в саду.'::text),
(304755,33862,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La gente se casa a menudo en interiores, pero esta pareja ... en un jardín hoy.'::text,'se está casando'::text,'se casa'::text,NULL::text,'La gente se casa a menudo en interiores, pero esta pareja se está casando en un jardín hoy.'::text),
(304754,33862,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les gens se marient souvent en intérieur, mais ce couple ... dans un jardin aujourd''hui.'::text,'est en train de se marier'::text,'se marie'::text,NULL::text,'Les gens se marient souvent en intérieur, mais ce couple est en train de se marier dans un jardin aujourd''hui.'::text),
(304757,33862,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İnsanlar genelde kapalı mekânda evlenir ama bu çift bugün bir bahçede ...'::text,'evleniyor'::text,'evlenir'::text,NULL::text,'İnsanlar genelde kapalı mekânda evlenir ama bu çift bugün bir bahçede evleniyor.'::text),
(304758,33862,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az emberek gyakran beltérben házasodnak, de ez a pár ma egy kertben ...'::text,'házasodik'::text,'házasodik'::text,NULL::text,'Az emberek gyakran beltérben házasodnak, de ez a pár ma egy kertben házasodik.'::text),
(310044,34450,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Mädchen hüpft mit ... Freundinnen auf dem Spielplatz.'::text,'ihren'::text,'seinen'::text,'seinen'::text,'Das Mädchen hüpft mit ihren Freundinnen auf dem Spielplatz.'::text),
(310048,34450,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дівчинка стрибає на майданчику зі ... друзями.'::text,'своїми'::text,'своїми'::text,'своїми'::text,'Дівчинка стрибає на майданчику зі своїми друзями.'::text),
(310047,34450,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La niña salta en el patio con ... amigos.'::text,'sus'::text,'sus'::text,'sus'::text,'La niña salta en el patio con sus amigos.'::text),
(310046,34450,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La fille saute dans la cour avec ... amis.'::text,'ses'::text,'ses'::text,'ses'::text,'La fille saute dans la cour avec ses amis.'::text),
(310049,34450,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kız oyun alanında ... arkadaşlarıyla sekiyor.'::text,'onun'::text,'onun'::text,'onun'::text,'Kız oyun alanında onun arkadaşlarıyla sekiyor.'::text),
(310050,34450,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A lány a játszótéren ugrál a ...'::text,'barátaival'::text,'barátaival'::text,'barátaival'::text,'A lány a játszótéren ugrál a barátaival.'::text),
(310071,34453,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tolle Arbeit: so viel ... auf dem Boden des Schulhofs.'::text,'Kreide'::text,'Kreide'::text,'eine Kreide'::text,'Tolle Arbeit: so viel Kreide auf dem Boden des Schulhofs.'::text),
(310075,34453,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чудова робота: стільки ... на підлозі майданчика.'::text,'крейди'::text,'крейди'::text,'крейди'::text,'Чудова робота: стільки крейди на підлозі майданчика.'::text),
(310074,34453,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Buen trabajo: tanta ... en el suelo del patio.'::text,'tiza'::text,'tiza'::text,'una tiza'::text,'Buen trabajo: tanta tiza en el suelo del patio.'::text),
(310073,34453,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beau travail : tellement de ... sur le sol de la cour.'::text,'craie'::text,'craie'::text,'une craie'::text,'Beau travail : tellement de craie sur le sol de la cour.'::text),
(310076,34453,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Harika iş: oyun alanının zemininde o kadar çok ... var.'::text,'tebeşir'::text,'tebeşirler'::text,'bir tebeşir'::text,'Harika iş: oyun alanının zemininde o kadar çok tebeşir var.'::text),
(310077,34453,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szép munka: annyi ... a játszótér talaján.'::text,'kréta'::text,'kréta'::text,'egy kréta'::text,'Szép munka: annyi kréta a játszótér talaján.'::text),
(296859,32985,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, ... gibt Oma Kekse? Keine Ahnung, irgendeine Frau mit Blumen.'::text,'wer'::text,'was'::text,'wo'::text,'Digga, wer gibt Oma Kekse? Keine Ahnung, irgendeine Frau mit Blumen.'::text),
(296863,32985,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, ... дає бабусі печиво? Хз, якась пані у квіточках.'::text,'хто'::text,'що'::text,'де'::text,'Бро, хто дає бабусі печиво? Хз, якась пані у квіточках.'::text),
(296862,32985,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ¿... le da galletas a la abuela? Ni idea, una señora de flores.'::text,'quién'::text,'qué'::text,'dónde'::text,'Tío, ¿quién le da galletas a la abuela? Ni idea, una señora de flores.'::text),
(296861,32985,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, ... donne des cookies à mamie ? Sais pas, une dame à fleurs.'::text,'qui'::text,'que'::text,'où'::text,'Frérot, qui donne des cookies à mamie ? Sais pas, une dame à fleurs.'::text),
(296864,32985,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, büyükanneye ... kurabiye veriyor? Bilmem, çiçekli bir kadın.'::text,'kim'::text,'ne'::text,'nerede'::text,'Kanka, büyükanneye kim kurabiye veriyor? Bilmem, çiçekli bir kadın.'::text),
(296865,32985,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ... ad kekszet a mamának? Passz, valami virágos néni.'::text,'ki'::text,'mi'::text,'hol'::text,'Tesó, ki ad kekszet a mamának? Passz, valami virágos néni.'::text),
(296877,32987,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bericht: Normalerweise schenken sie Karten, aber gestern ... sie ihr 12 Geschenke.'::text,'gaben'::text,'geben'::text,NULL::text,'Bericht: Normalerweise schenken sie Karten, aber gestern gaben sie ihr 12 Geschenke.'::text),
(296881,32987,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Звіт: вони зазвичай дарують листівки, але вчора ... їй 12 подарунків.'::text,'подарували'::text,'дарують'::text,NULL::text,'Звіт: вони зазвичай дарують листівки, але вчора подарували їй 12 подарунків.'::text),
(296880,32987,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Informe: ellos suelen regalar tarjetas, pero ayer le ... 12 regalos.'::text,'dieron'::text,'dan'::text,NULL::text,'Informe: ellos suelen regalar tarjetas, pero ayer le dieron 12 regalos.'::text),
(296879,32987,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rapport : d''habitude ils offrent des cartes, mais hier ils lui ... 12 cadeaux.'::text,'ont donné'::text,'donnent'::text,NULL::text,'Rapport : d''habitude ils offrent des cartes, mais hier ils lui ont donné 12 cadeaux.'::text),
(296882,32987,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rapor: onlar genelde kart verir ama dün ona 12 hediye ...'::text,'verdi'::text,'verir'::text,NULL::text,'Rapor: onlar genelde kart verir ama dün ona 12 hediye verdi.'::text),
(296883,32987,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jelentés: ők általában képeslapot adnak, de tegnap 12 ajándékot ... neki.'::text,'adtak'::text,'adnak'::text,NULL::text,'Jelentés: ők általában képeslapot adnak, de tegnap 12 ajándékot adtak neki.'::text),
(315705,35079,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ist die Kundin geschockt? Wegen der Neuigkeit der Friseurin.'::text,'Warum'::text,'Wo'::text,'Wer'::text,'Warum ist die Kundin geschockt? Wegen der Neuigkeit der Friseurin.'::text),
(315709,35079,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... клієнтка шокована? Через новину від перукарки.'::text,'Чому'::text,'Де'::text,'Хто'::text,'Чому клієнтка шокована? Через новину від перукарки.'::text),
