(315710,35079,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Müşteri ... şokta? Kuaförün haberi yüzünden.'::text,'neden'::text,'nerede'::text,'kim'::text,'Müşteri neden şokta? Kuaförün haberi yüzünden.'::text),
