(315732,35082,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Geschockte Frauen starren ... auf den schlimmsten Haarschnitt aller Zeiten!'::text,'schweigend'::text,'schweigend'::text,'Schweigen'::text,'Geschockte Frauen starren schweigend auf den schlimmsten Haarschnitt aller Zeiten!'::text),
