(307488,34166,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, sein Shirt ... so orange, ich brauch gleich eine Sonnenbrille.'::text,'ist'::text,'sind'::text,'bin'::text,'Digga, sein Shirt ist so orange, ich brauch gleich eine Sonnenbrille.'::text),
(307492,34166,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, його майка ... така помаранчева, треба буде сонцезахисні окуляри.'::text,'є'::text,'є'::text,'є'::text,'Бро, його майка є така помаранчева, треба буде сонцезахисні окуляри.'::text),
(307491,34166,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, su camiseta ... tan naranja que voy a necesitar gafas de sol.'::text,'es'::text,'son'::text,'soy'::text,'Tío, su camiseta es tan naranja que voy a necesitar gafas de sol.'::text),
(307490,34166,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, son haut ... tellement orange, je vais avoir besoin de lunettes de soleil.'::text,'est'::text,'sont'::text,'suis'::text,'Frérot, son haut est tellement orange, je vais avoir besoin de lunettes de soleil.'::text),
(307493,34166,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, onun üstü o kadar turuncu ... ki güneş gözlüğü lazım olacak.'::text,''::text,NULL::text,NULL::text,'Kanka, onun üstü o kadar turuncu ki güneş gözlüğü lazım olacak.'::text),
(307494,34166,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a felsője ... annyira narancssárga, napszemüveg kell majd.'::text,''::text,NULL::text,'vagyok'::text,'Tesó, a felsője annyira narancssárga, napszemüveg kell majd.'::text),
(307533,34171,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katastrophe! Er trinkt immer ein Glas, aber jetzt ... er den orangen Krug!'::text,'leert'::text,'leert'::text,NULL::text,'Katastrophe! Er trinkt immer ein Glas, aber jetzt leert er den orangen Krug!'::text),
(307537,34171,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Катастрофа! Він завжди п''є одну склянку, а тепер ... помаранчевий глечик!'::text,'спорожнює'::text,'спорожнює'::text,NULL::text,'Катастрофа! Він завжди п''є одну склянку, а тепер спорожнює помаранчевий глечик!'::text),
(307536,34171,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Desastre! ¡Él siempre bebe un vaso, pero ahora ... la jarra naranja!'::text,'está vaciando'::text,'vacía'::text,NULL::text,'¡Desastre! ¡Él siempre bebe un vaso, pero ahora está vaciando la jarra naranja!'::text),
(307535,34171,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Catastrophe ! Il boit toujours un verre, mais là il ... la carafe orange !'::text,'est en train de vider'::text,'vide'::text,NULL::text,'Catastrophe ! Il boit toujours un verre, mais là il est en train de vider la carafe orange !'::text),
(307538,34171,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Felaket! O hep bir bardak içer ama şimdi turuncu sürahiyi ...!'::text,'boşaltıyor'::text,'boşaltır'::text,NULL::text,'Felaket! O hep bir bardak içer ama şimdi turuncu sürahiyi boşaltıyor!'::text),
(307539,34171,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katasztrófa! Ő mindig egy pohárral iszik, de most ... a narancssárga kancsót!'::text,'üríti'::text,'üríti'::text,NULL::text,'Katasztrófa! Ő mindig egy pohárral iszik, de most üríti a narancssárga kancsót!'::text),
(309432,34382,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... die roten Tomaten pflücken, nicht die grünen.'::text,'kann'::text,'kann'::text,'kann'::text,'Er kann die roten Tomaten pflücken, nicht die grünen.'::text),
(309436,34382,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... зривати червоні помідори, а не зелені.'::text,'може'::text,'може'::text,'може'::text,'Він може зривати червоні помідори, а не зелені.'::text),
(309435,34382,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... recoger los tomates rojos, no los verdes.'::text,'puede'::text,'puede'::text,'puede'::text,'Él puede recoger los tomates rojos, no los verdes.'::text),
(309434,34382,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... cueillir les tomates rouges, pas les vertes.'::text,'peut'::text,'peut'::text,'peut'::text,'Il peut cueillir les tomates rouges, pas les vertes.'::text),
(309437,34382,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O kırmızı domatesleri ..., yeşilleri değil.'::text,'toplayabilir'::text,'toplayabilir'::text,'toplayabilir'::text,'O kırmızı domatesleri toplayabilir, yeşilleri değil.'::text),
(309438,34382,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő a piros paradicsomokat ..., nem a zöldeket.'::text,'szedheti'::text,'szedheti'::text,'szedheti'::text,'Ő a piros paradicsomokat szedheti, nem a zöldeket.'::text),
(309468,34386,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tomaten wachsen an Pflanzen, also ... er sie von der Pflanze pflücken.'::text,'muss'::text,'muss'::text,'sollte'::text,'Tomaten wachsen an Pflanzen, also muss er sie von der Pflanze pflücken.'::text),
(309472,34386,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Помідори ростуть на рослинах, тож він ... зривати їх з рослини.'::text,'має'::text,'мусить'::text,'мав би'::text,'Помідори ростуть на рослинах, тож він має зривати їх з рослини.'::text),
(309471,34386,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los tomates crecen en plantas, así que él ... arrancarlos de la planta.'::text,'tiene que'::text,'debe'::text,'debería'::text,'Los tomates crecen en plantas, así que él tiene que arrancarlos de la planta.'::text),
(309470,34386,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les tomates poussent sur des plants, donc il ... les cueillir sur le plant.'::text,'doit'::text,'doit'::text,'devrait'::text,'Les tomates poussent sur des plants, donc il doit les cueillir sur le plant.'::text),
(309473,34386,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Domatesler bitkide yetişir, bu yüzden o onları bitkiden ...'::text,'koparmak zorunda'::text,'koparmalı'::text,'koparmalı'::text,'Domatesler bitkide yetişir, bu yüzden o onları bitkiden koparmak zorunda.'::text),
(309474,34386,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A paradicsom növényen nő, ezért neki le ... szednie őket a növényről.'::text,'kell'::text,'kell'::text,'kellene'::text,'A paradicsom növényen nő, ezért neki le kell szednie őket a növényről.'::text),
(299262,33252,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihre Hand liegt auf ... Herz! Der schlimmste Tag überhaupt!'::text,'ihrem'::text,'seinem'::text,'seinem'::text,'Ihre Hand liegt auf ihrem Herz! Der schlimmste Tag überhaupt!'::text),
(299266,33252,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її рука на ... серці! Найгірший день в історії!'::text,'її'::text,'його'::text,'його'::text,'Її рука на її серці! Найгірший день в історії!'::text),
(299265,33252,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Su mano está sobre ... corazón! ¡El peor día de la historia!'::text,'su'::text,'su'::text,'su'::text,'¡Su mano está sobre su corazón! ¡El peor día de la historia!'::text),
(299264,33252,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sa main est sur ... cœur ! Le pire jour de tous !'::text,'son'::text,'son'::text,'son'::text,'Sa main est sur son cœur ! Le pire jour de tous !'::text),
