(299289,33255,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, anscheinend braucht ihr Herz nach dem Spiel so viel ...'::text,'Luft'::text,'Luft'::text,'eine Luft'::text,'Bestie, anscheinend braucht ihr Herz nach dem Spiel so viel Luft.'::text),
(299293,33255,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бесті, кажуть, її серцю після тієї гри треба стільки ...'::text,'повітря'::text,'повітря'::text,'повітря'::text,'Бесті, кажуть, її серцю після тієї гри треба стільки повітря.'::text),
(299292,33255,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, al parecer su corazón necesita tanto ... después de ese partido.'::text,'aire'::text,'aire'::text,'un aire'::text,'Bestie, al parecer su corazón necesita tanto aire después de ese partido.'::text),
(299291,33255,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, apparemment son cœur a besoin de tellement ... après ce match.'::text,'d''air'::text,'d''air'::text,'d''un air'::text,'Bestie, apparemment son cœur a besoin de tellement d''air après ce match.'::text),
(299294,33255,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, görünüşe göre o maçtan sonra kalbinin çok fazla ... ihtiyacı var.'::text,'havaya'::text,'havalara'::text,'bir havaya'::text,'Kanka, görünüşe göre o maçtan sonra kalbinin çok fazla havaya ihtiyacı var.'::text),
(299295,33255,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag a szívének annyi ... kell a meccs után.'::text,'levegő'::text,'levegő'::text,'egy levegő'::text,'Csajszi, állítólag a szívének annyi levegő kell a meccs után.'::text),
(297363,33041,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Frau ist für den Schirm des Jungen ... als je zuvor.'::text,'dankbarer'::text,'dankbarer'::text,'am dankbarsten'::text,'Die Frau ist für den Schirm des Jungen dankbarer als je zuvor.'::text),
(297367,33041,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жінка ... за парасольку хлопчика, ніж будь-коли.'::text,'більш вдячна'::text,'вдячніша'::text,'найвдячніша'::text,'Жінка більш вдячна за парасольку хлопчика, ніж будь-коли.'::text),
(297366,33041,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mujer está ... que nunca por el paraguas del chico.'::text,'más agradecida'::text,'más agradecida'::text,'la más agradecida'::text,'La mujer está más agradecida que nunca por el paraguas del chico.'::text),
(297365,33041,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La femme est ... que jamais pour le parapluie du garçon.'::text,'plus reconnaissante'::text,'plus reconnaissante'::text,'la plus reconnaissante'::text,'La femme est plus reconnaissante que jamais pour le parapluie du garçon.'::text),
(297368,33041,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kadın, çocuğun şemsiyesi için her zamankinden ...'::text,'daha minnettar'::text,'daha minnettar'::text,'en minnettar'::text,'Kadın, çocuğun şemsiyesi için her zamankinden daha minnettar.'::text),
(297369,33041,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nő a fiú esernyőjéért ..., mint valaha.'::text,'hálásabb'::text,'hálásabb'::text,'leghálásabb'::text,'A nő a fiú esernyőjéért hálásabb, mint valaha.'::text),
(314139,34905,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihr zwei ... im selben Kleid, und ehrlich, ikonisch.'::text,'seid'::text,'ist'::text,'bin'::text,'Ihr zwei seid im selben Kleid, und ehrlich, ikonisch.'::text),
(314143,34905,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ви двоє ... в однаковій сукні, і чесно, культово.'::text,'є'::text,'є'::text,'є'::text,'Ви двоє є в однаковій сукні, і чесно, культово.'::text),
(314142,34905,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vosotras dos ... con el mismo vestido, y en serio, icónico.'::text,'estáis'::text,'está'::text,'estoy'::text,'Vosotras dos estáis con el mismo vestido, y en serio, icónico.'::text),
(314141,34905,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vous deux ... dans la même robe, et franchement, iconique.'::text,'êtes'::text,'est'::text,'suis'::text,'Vous deux êtes dans la même robe, et franchement, iconique.'::text),
(314144,34905,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Siz ikiniz aynı elbiseyle ..., ve açıkçası efsane.'::text,''::text,NULL::text,NULL::text,'Siz ikiniz aynı elbiseyle, ve açıkçası efsane.'::text),
(314145,34905,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ti ketten ugyanabban a ruhában ..., és őszintén, ikonikus.'::text,'vagytok'::text,'van'::text,'vagyok'::text,'Ti ketten ugyanabban a ruhában vagytok, és őszintén, ikonikus.'::text),
(314202,34912,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, sie hat gesagt, dass sie das gleiche Kleid haben, ... sie sind immer noch Freundinnen.'::text,'aber'::text,'also'::text,'weil'::text,'Hör zu, sie hat gesagt, dass sie das gleiche Kleid haben, aber sie sind immer noch Freundinnen.'::text),
(314206,34912,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, вона сказала, що в них однакова сукня, ... вони досі подруги.'::text,'але'::text,'тому'::text,'бо'::text,'Слухай, вона сказала, що в них однакова сукня, але вони досі подруги.'::text),
(314205,34912,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, ella dijo que tienen el mismo vestido, ... siguen siendo amigas.'::text,'pero'::text,'así que'::text,'porque'::text,'Oye, ella dijo que tienen el mismo vestido, pero siguen siendo amigas.'::text),
(314204,34912,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, elle a dit qu''elles ont la même robe, ... elles sont toujours amies.'::text,'mais'::text,'donc'::text,'parce que'::text,'Écoute, elle a dit qu''elles ont la même robe, mais elles sont toujours amies.'::text),
(314207,34912,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, o aynı elbiseleri olduğunu söyledi, ... hâlâ arkadaşlar.'::text,'ama'::text,'bu yüzden'::text,'çünkü'::text,'Dinle, o aynı elbiseleri olduğunu söyledi, ama hâlâ arkadaşlar.'::text),
(314208,34912,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, ő azt mondta, hogy ugyanolyan ruhájuk van, ... még mindig barátnők.'::text,'de'::text,'ezért'::text,'mert'::text,'Figyelj, ő azt mondta, hogy ugyanolyan ruhájuk van, de még mindig barátnők.'::text),
(305391,33933,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie liest ... Nachrichten auf ihrem Handy immer wieder.'::text,'diese'::text,'diese'::text,'jene'::text,'Sie liest diese Nachrichten auf ihrem Handy immer wieder.'::text),
(305395,33933,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона знову й знову перечитує ... повідомлення в телефоні.'::text,'ці'::text,'це'::text,'те'::text,'Вона знову й знову перечитує ці повідомлення в телефоні.'::text),
(305394,33933,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella lee ... mensajes en su móvil una y otra vez.'::text,'estos'::text,'este'::text,'ese'::text,'Ella lee estos mensajes en su móvil una y otra vez.'::text),
(305393,33933,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle lit ... messages sur son téléphone encore et encore.'::text,'ces'::text,'ce'::text,'ce'::text,'Elle lit ces messages sur son téléphone encore et encore.'::text),
(305396,33933,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O telefonundaki ... mesajları tekrar tekrar okuyor.'::text,'bu'::text,'bu'::text,'şu'::text,'O telefonundaki bu mesajları tekrar tekrar okuyor.'::text),
(305397,33933,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő újra meg újra elolvassa ... az üzeneteket a telefonján.'::text,'ezeket'::text,'ezt'::text,'azt'::text,'Ő újra meg újra elolvassa ezeket az üzeneteket a telefonján.'::text),
(305427,33937,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Warte, anscheinend ... zehn neue Nachrichten auf ihrem Handy.'::text,'sind'::text,'ist'::text,'sein'::text,'Warte, anscheinend sind zehn neue Nachrichten auf ihrem Handy.'::text),
(305431,33937,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чекай, кажуть, у її телефоні ... десять нових повідомлень.'::text,'є'::text,'є'::text,'бути'::text,'Чекай, кажуть, у її телефоні є десять нових повідомлень.'::text),
(305430,33937,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Espera, al parecer ... diez mensajes nuevos en su móvil.'::text,'hay'::text,'hay'::text,'hay'::text,'Espera, al parecer hay diez mensajes nuevos en su móvil.'::text),
(305429,33937,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Attends, apparemment ... dix nouveaux messages sur son téléphone.'::text,'il y a'::text,'il y a'::text,'il y a'::text,'Attends, apparemment il y a dix nouveaux messages sur son téléphone.'::text),
(305432,33937,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bekle, görünüşe göre telefonunda on yeni mesaj ...'::text,'var'::text,'var'::text,'olmak'::text,'Bekle, görünüşe göre telefonunda on yeni mesaj var.'::text),
(305433,33937,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Várj, állítólag tíz új üzenet ... a telefonján.'::text,'van'::text,'van'::text,'lenni'::text,'Várj, állítólag tíz új üzenet van a telefonján.'::text)
) v(id, eid, lang, n_intro_text, n_correct_answer, n_distractor_1, n_distractor_2, n_full_sentence, o_intro_text, o_correct_answer, o_distractor_1, o_distractor_2, o_full_sentence)
where l.id = v.id and l.exercise_id = v.eid and l.language_code = v.lang and l.intro_text is not distinct from v.o_intro_text and l.correct_answer is not distinct from v.o_correct_answer and l.distractor_1 is not distinct from v.o_distractor_1 and l.distractor_2 is not distinct from v.o_distractor_2 and l.full_sentence is not distinct from v.o_full_sentence
returning l.id;
